@font-face {
  font-family: "Ubuntu";
  src: url("data:font/ttf;base64,") format("truetype");
  font-weight: 400;
}
@font-face {
  font-family: "Ubuntu";
  src: url("data:font/ttf;base64,") format("truetype");
  font-weight: 500 700;
}
@font-face {
  font-family: "Ubuntu";
  src: url("data:font/ttf;base64,") format("truetype");
  font-weight: 800;
}

:root {
  color-scheme: dark;
  font-family: "Ubuntu", "Segoe UI", Arial, sans-serif;
  background: transparent;
  --bg: #121315;
  --sidebar: rgba(22, 22, 24, .96);
  --card: rgba(29, 29, 31, .96);
  --card-hover: rgba(36, 36, 38, .98);
  --control: rgba(27, 27, 29, .96);
  --control-hover: rgba(38, 38, 40, .98);
  --line: rgba(255, 255, 255, .105);
  --line-soft: rgba(255, 255, 255, .065);
  --line-bright: rgba(255, 255, 255, .15);
  --text: #f5f5f5;
  --muted: #8d8d8d;
  --accent: #f1f1f1;
  --menu-accent: #f1f1f1;
  --on-accent: #08090b;
  --menu-on-accent: #08090b;
  --on-enabled: #08090b;
  --on-tertiary: #08090b;
  --background: #08090b;
  --background-alt: #171b24;
  --app-background: #08090b;
  --background-media-opacity: .35;
  --background-media-blur: 0px;
  --background-media-fit: cover;
  --accent-soft: rgba(255, 255, 255, .10);
  --enabled: #55e3a4;
  --enabled-soft: rgba(85, 227, 164, .13);
  --tertiary: #d4a653;
  --panel-shadow: 0 18px 44px rgba(0, 0, 0, .26), inset 0 1px 0 rgba(255, 255, 255, .055);
  --control-inset: inset 0 1px 0 rgba(255,255,255,.035), inset 0 2px 8px rgba(0,0,0,.42);
  --card-surface: radial-gradient(circle at 14% -10%, rgba(255,255,255,.062), transparent 40%), linear-gradient(150deg, rgba(33,34,37,.95), rgba(17,18,21,.975));
  --motion: cubic-bezier(.2, .82, .25, 1);
  --elastic: cubic-bezier(.22, .92, .28, 1.04);
  --startup-panel-width: clamp(315px, 38vw, 380px);
  /* Shared component geometry. New controls must use these tokens instead of
     introducing another local copy of the same dimensions. */
  --ui-page-padding-top: 18px;
  --ui-page-padding-inline: 20px;
  --ui-page-padding-bottom: 24px;
  --ui-card-gap: 14px;
  --ui-card-radius: 16px;
  --ui-card-padding: 16px;
  --ui-card-compact-padding-block: 14px;
  --ui-feature-padding-block: 13px;
  --ui-feature-padding-inline: 15px;
  --ui-card-header-min-height: 34px;
  /* Keep card titles and switches centered between the top edge and divider. */
  --ui-feature-header-divider-gap: var(--ui-feature-padding-block);
  --ui-row-gap: 18px;
  --ui-master-row-min-height: 60px;
  --ui-option-row-min-height: var(--ui-icon-action-size);
  --ui-option-row-gap: 10px;
  --ui-stack-control-gap: 10px;
  --ui-option-list-gap: 7px;
  --ui-settings-row-min-height: 53px;
  --ui-settings-row-padding-block: 8px;
  --ui-workspace-header-height: 68px;
  --ui-workspace-header-gap: 12px;
  --ui-window-titlebar-bg: rgba(29, 29, 31, .902);
  --ui-window-action-size: 38px;
  --ui-window-action-radius: 11px;
  --ui-window-action-edge-inset: 16px;
  --ui-window-action-gap: 8px;
  --ui-window-titlebar-leading-inset: 20px;
  --ui-preference-gap: 24px;
  --ui-preference-min-height: 68px;
  --ui-preference-padding-block: 12px;
  --ui-preference-padding-inline: 14px;
  --ui-control-height: 36px;
  --ui-control-radius: 10px;
  --ui-range-height: 32px;
  --ui-pill-radius: 999px;
  --ui-action-height: 38px;
  --ui-action-padding-block: 7px;
  --ui-action-padding-inline: 14px;
  --ui-action-radius: 10px;
  --ui-action-font-size: 14px;
  --ui-action-font-weight: 650;
  --ui-icon-action-size: 34px;
  --ui-icon-action-radius: 9px;
  --ui-segment-height: 40px;
  --ui-toggle-width: 50px;
  --ui-toggle-height: 28px;
  --ui-toggle-thumb-size: 20px;
  --ui-toggle-inset: 4px;
  --ui-toggle-travel: 22px;
}

* { box-sizing: border-box; }
html, body { position:fixed;inset:0;width: 100%; height: 100%; margin: 0; overflow: hidden; overscroll-behavior:none;user-select: none; }
body { color:var(--text);background:#111214;opacity:1; }
html.native-dwm-backdrop {
  --bg:rgba(18,19,21,.76);
  --sidebar:rgba(22,22,24,.78);
}
html.native-dwm-backdrop body { background: transparent; }
html.native-dwm-backdrop .workspace { background: radial-gradient(circle at 50% -160px, rgba(255,255,255,.045), transparent 44%), linear-gradient(160deg, rgba(8,8,8,.58), rgba(2,2,2,.68)); }
html.native-dwm-backdrop .card { background:radial-gradient(circle at 14% -10%,rgba(255,255,255,.052),transparent 40%),linear-gradient(150deg,rgba(27,28,30,.88),rgba(13,14,16,.93)); }
/* The loader may start its sweep only after the native state has supplied the
   saved palette. Keep the uninitialized default surface out of the reveal if
   a delayed WebView message ever arrives out of order. */
html.startup-transition-preparing:not(.appearance-ready) .app-shell,
html.startup-transition-running:not(.appearance-ready) .app-shell { visibility:hidden; }
button, input, select { font: inherit; }
button, select, label { -webkit-tap-highlight-color: transparent; }
button { color: inherit; }

.training-range-card{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:center;gap:13px;min-height:74px}.training-range-icon{display:grid;width:42px;height:42px;place-items:center;border:1px solid var(--line);border-radius:12px;color:var(--text);background:var(--control);box-shadow:var(--control-inset)}.training-range-icon .lucide-icon{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.training-range-copy{display:grid;min-width:0;gap:4px}.training-range-copy strong{font-size:14px}.training-range-copy small{overflow:hidden;color:var(--muted);font-size:10px;text-overflow:ellipsis;white-space:nowrap}.training-range-actions{display:flex;align-items:center;gap:8px}.training-range-settings{display:grid;width:36px;height:36px;place-items:center;padding:0;border:1px solid var(--line);border-radius:10px;color:var(--muted);background:var(--control);cursor:pointer}.training-range-settings .lucide-icon{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.training-range-launch{min-width:105px}.training-range-card.is-desktop-only{opacity:.68}.training-range-card button:disabled{cursor:not-allowed;opacity:.55}.training-settings-modal{position:fixed;z-index:360;inset:0;display:grid;place-items:center;padding:22px;background:rgba(3,5,7,.72);backdrop-filter:blur(12px)}.training-settings-modal[hidden]{display:none}.training-settings-panel{display:grid;width:min(560px,calc(100vw - 44px));max-height:calc(100vh - 44px);overflow:hidden;border:1px solid var(--line-bright);border-radius:18px;background:var(--card);box-shadow:0 30px 90px rgba(0,0,0,.55),inset 0 1px rgba(255,255,255,.05)}.training-settings-panel>.window-titlebar{position:relative}.training-settings-body{display:grid;gap:2px;padding:10px 20px 14px;overflow:auto}.training-settings-body>.select-row,.training-settings-body>.range-row{min-height:64px;border-bottom:1px solid var(--line-soft)}.training-settings-body>.range-row:last-child{border-bottom:0}.training-settings-panel>footer{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 20px;border-top:1px solid var(--line);background:rgba(0,0,0,.08)}.training-settings-panel>footer>small{color:var(--muted);font-size:9px}.training-settings-panel>footer>button{min-width:90px}
.tutorial-replay-card{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:center;gap:13px;min-height:74px}.tutorial-replay-icon{display:grid;width:42px;height:42px;place-items:center;border:1px solid color-mix(in srgb,var(--accent) 26%,var(--line));border-radius:12px;color:var(--text);background:color-mix(in srgb,var(--accent) 8%,transparent)}.tutorial-replay-icon .lucide-icon{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.tutorial-replay-copy{display:grid;min-width:0;gap:4px}.tutorial-replay-copy strong{font-size:14px}.tutorial-replay-copy small{overflow:hidden;color:var(--muted);font-size:10px;text-overflow:ellipsis;white-space:nowrap}.tutorial-replay-open{min-width:105px}
.brand-links-card[hidden]{display:none}.brand-links-heading{justify-content:space-between;gap:16px;margin-bottom:11px}.brand-links-name{max-width:220px;padding:6px 10px;overflow:hidden;border:1px solid color-mix(in srgb,var(--accent) 28%,var(--line));border-radius:9px;color:var(--text);background:color-mix(in srgb,var(--accent) 7%,var(--control));font-size:10px;font-weight:700;line-height:1;text-overflow:ellipsis;white-space:nowrap}.brand-links-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.brand-link-button{display:grid;grid-template-columns:38px minmax(0,1fr) 15px;align-items:center;gap:11px;min-height:66px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;color:var(--text);background:linear-gradient(145deg,color-mix(in srgb,var(--control) 94%,var(--text) 6%),var(--control));box-shadow:var(--control-inset);cursor:pointer;text-align:left;transition:border-color 150ms ease,background 150ms ease,transform 150ms ease,box-shadow 150ms ease}.brand-link-button[hidden]{display:none}.brand-link-button:hover{border-color:color-mix(in srgb,var(--accent) 34%,var(--line));background:color-mix(in srgb,var(--accent) 6%,var(--control-hover));box-shadow:var(--control-inset),0 9px 22px color-mix(in srgb,var(--background) 24%,transparent);transform:translateY(-1px)}.brand-link-button:focus-visible{outline:2px solid color-mix(in srgb,var(--accent) 62%,transparent);outline-offset:2px}.brand-link-icon{display:grid;width:38px;height:38px;place-items:center;border:1px solid var(--line);border-radius:11px;background:color-mix(in srgb,var(--background) 36%,transparent)}.brand-link-icon svg{width:21px;height:21px}.brand-link-website .brand-link-icon{color:var(--accent)}.brand-link-telegram .brand-link-icon{color:#26a5e4}.brand-link-discord .brand-link-icon{color:#5865f2}.brand-link-youtube .brand-link-icon{color:#ff4a55}.brand-link-button>span:nth-child(2){display:grid;min-width:0;gap:4px}.brand-link-button strong{overflow:hidden;font-size:13px;font-weight:680;text-overflow:ellipsis;white-space:nowrap}.brand-link-button small{overflow:hidden;color:var(--muted);font-size:9.5px;text-overflow:ellipsis;white-space:nowrap}.brand-link-open{width:15px;height:15px;fill:none;stroke:var(--muted);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;transition:stroke 150ms ease,transform 150ms ease}.brand-link-button:hover .brand-link-open{stroke:var(--text);transform:translate(1px,-1px)}@media(max-width:700px){.brand-links-grid{grid-template-columns:1fr}.brand-links-name{max-width:140px}}
.brand-link-button:not(.brand-link-website) .brand-link-icon svg{fill:currentColor}

/* Training settings reuse the same modal, row and pill geometry as the rest
   of NAIM instead of stretching range controls into preference rows. */
.training-settings-modal { background:color-mix(in srgb,var(--bg) 76%,transparent);backdrop-filter:blur(14px) saturate(.55); }
.training-settings-panel { width:min(580px,calc(100vw - 44px));border-color:var(--line-bright);color:var(--text);background:radial-gradient(circle at 12% -8%,color-mix(in srgb,var(--text) 5%,transparent),transparent 38%),var(--bg);box-shadow:0 30px 90px rgba(0,0,0,.55),inset 0 1px color-mix(in srgb,var(--text) 6%,transparent); }
.training-settings-panel>.window-titlebar { display:flex;min-height:var(--ui-workspace-header-height);align-items:center;justify-content:space-between;gap:var(--ui-workspace-header-gap);padding:0 16px 0 20px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--card) 78%,transparent); }
.training-settings-panel>.window-titlebar>span { display:grid;min-width:0;gap:4px; }
.training-settings-panel>.window-titlebar strong { color:var(--text);font-size:16px;line-height:1.1; }
.training-settings-panel>.window-titlebar small { overflow:hidden;color:var(--muted);font-size:10px;line-height:1.2;text-overflow:ellipsis;white-space:nowrap; }
.training-settings-panel>.window-titlebar>.workspace-close { position:relative;top:auto;right:auto;flex:0 0 var(--ui-window-action-size); }
.training-settings-body { gap:0;padding:7px 20px 13px; }
.training-settings-body>.select-row { min-height:62px;border-bottom:1px solid var(--line-soft); }
.training-settings-range { display:grid;gap:9px;padding:13px 0 15px;border-bottom:1px solid var(--line-soft); }
.training-settings-range:last-child { border-bottom:0; }
.training-settings-range>.setting-group-head { min-height:18px;margin:0;padding:0 2px; }
.training-settings-range>.setting-group-head strong { font-size:13px; }
.training-settings-range>.setting-group-head small { font-size:10px; }
.training-settings-range>.range-row { width:100%;height:var(--ui-range-height);min-height:var(--ui-range-height);margin:0; }
.training-settings-panel>footer { background:color-mix(in srgb,var(--card) 68%,transparent); }

.anti-flash-crosshair-modal { z-index:390; }
.anti-flash-crosshair-panel { width:min(720px,calc(100vw - 44px)); }
.anti-flash-crosshair-editor { display:grid;grid-template-columns:minmax(220px,.82fr) minmax(330px,1.18fr);min-height:390px;overflow:hidden; }
.anti-flash-crosshair-stage { position:relative;min-height:390px;overflow:hidden;border-right:1px solid var(--line);background-color:#030303;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);background-position:center;background-size:48px 48px,48px 48px,12px 12px,12px 12px;box-shadow:inset -36px 0 60px rgba(0,0,0,.18); }
.anti-flash-crosshair-stage::before,.anti-flash-crosshair-stage::after { content:"";position:absolute;background:rgba(255,255,255,.085);pointer-events:none; }
.anti-flash-crosshair-stage::before { left:50%;top:0;width:1px;height:100%; }
.anti-flash-crosshair-stage::after { left:0;top:50%;width:100%;height:1px; }
.anti-flash-crosshair-grid-label { position:absolute;left:14px;top:13px;color:rgba(255,255,255,.34);font-size:9px;font-weight:700;letter-spacing:.16em; }
.anti-flash-crosshair-preview { --crosshair-color:#fff;--crosshair-gap:6px;--crosshair-length:0px;--crosshair-thickness:2px;--crosshair-dot:4px;--crosshair-opacity:1;position:absolute;inset:0;opacity:var(--crosshair-opacity);filter:drop-shadow(0 0 3px rgba(0,0,0,.92));pointer-events:none; }
.anti-flash-crosshair-preview i,.anti-flash-crosshair-preview b { position:absolute;display:block;border-radius:999px;background:var(--crosshair-color); }
.anti-flash-crosshair-preview i:nth-child(1),.anti-flash-crosshair-preview i:nth-child(2) { left:50%;width:var(--crosshair-thickness);height:var(--crosshair-length);transform:translateX(-50%); }
.anti-flash-crosshair-preview i:nth-child(1) { top:calc(50% - var(--crosshair-gap) - var(--crosshair-length)); }
.anti-flash-crosshair-preview i:nth-child(2) { top:calc(50% + var(--crosshair-gap)); }
.anti-flash-crosshair-preview i:nth-child(3),.anti-flash-crosshair-preview i:nth-child(4) { top:50%;width:var(--crosshair-length);height:var(--crosshair-thickness);transform:translateY(-50%); }
.anti-flash-crosshair-preview i:nth-child(3) { left:calc(50% - var(--crosshair-gap) - var(--crosshair-length)); }
.anti-flash-crosshair-preview i:nth-child(4) { left:calc(50% + var(--crosshair-gap)); }
.anti-flash-crosshair-preview b { left:50%;top:50%;width:var(--crosshair-dot);height:var(--crosshair-dot);transform:translate(-50%,-50%); }
.anti-flash-crosshair-panel .training-settings-body { max-height:390px;padding-top:9px; }
.anti-flash-crosshair-color-row { min-height:54px;margin-bottom:2px;border-bottom:1px solid var(--line-soft); }
.anti-flash-crosshair-panel .training-settings-range { padding-block:10px 12px; }
.anti-flash-crosshair-panel .training-settings-range>.range-row { height:50px;min-height:50px; }
@media (max-width:680px) {
  .anti-flash-crosshair-editor { grid-template-columns:1fr;overflow:auto; }
  .anti-flash-crosshair-stage { min-height:190px;border-right:0;border-bottom:1px solid var(--line); }
  .anti-flash-crosshair-panel .training-settings-body { max-height:none; }
}

.startup-loader-frame { position: fixed; z-index: 1000; inset: 0; width: 100%; height: 100%; overflow: hidden; border: 0; border-radius: 10px; opacity: 1; visibility: visible; background: #05060a; clip-path: inset(0 0 0 0 round 10px); pointer-events: auto; }
/* Precompose setup below the startup curtain, not above its reveal animation. */
html:not(.startup-transition-complete) .first-login-onboarding { z-index: 999; pointer-events: none; }
.startup-reveal-panel { position: fixed; z-index: 1001; left: 0; top: 0; display: block; width: var(--startup-panel-width); height: 100%; overflow: hidden; border-right: 1px solid var(--line-bright); border-radius: 10px 0 0 10px; opacity: 0; visibility: hidden; color: var(--text); background: var(--sidebar); box-shadow: 18px 0 42px rgba(0,0,0,.22), inset -1px 0 rgba(255,255,255,.025); transform: translate3d(0,0,0); pointer-events: none; will-change: transform; }
.startup-reveal-panel::before { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 16% 8%, rgba(255,255,255,.045), transparent 26%), linear-gradient(90deg, transparent 72%, rgba(255,255,255,.018)); }
.startup-reveal-brand { position: absolute; z-index: 1; left: 50%; top: calc(50% - 166px); display: flex; width: max-content; align-items: center; gap: 11px; opacity: .94; translate: -50% 0; transform: translateY(0); }
.startup-reveal-brand svg { width: 32px; height: 40px; fill: currentColor; filter: drop-shadow(0 0 14px rgba(255,255,255,.10)); }
.startup-reveal-brand .brand-remote-logo { width:40px;height:40px;object-fit:contain;filter:drop-shadow(0 0 14px color-mix(in srgb,var(--accent) 16%,transparent)); }
.startup-reveal-brand.is-wide-logo { width:120px;max-width:calc(100% - 36px); }
.startup-reveal-brand.is-wide-logo .brand-remote-logo { width:120px;height:40px;max-width:100%;flex:0 1 120px; }
.startup-reveal-brand.is-wide-logo>span { display:none; }
.startup-reveal-brand>span { display:grid;gap:3px;text-align:left; }
.startup-reveal-brand.is-logo-less>span { text-align:center; }
.startup-reveal-brand strong { font-size: 18px;line-height:1;font-weight:700;letter-spacing:.08em; }
.startup-reveal-brand small { color:var(--muted);font-size:11px;line-height:1;font-weight:600;letter-spacing:.09em; }
.startup-reveal-line { position: absolute; z-index: 2; right: 0; top: 12%; width: 1px; height: 76%; border-radius: 2px; background: linear-gradient(180deg, transparent, rgba(255,255,255,.30) 25%, #fff 50%, rgba(85,227,164,.48) 70%, transparent); box-shadow: 0 0 18px rgba(255,255,255,.24), 0 0 30px rgba(85,227,164,.10); }
.startup-reveal-edge { position: fixed; z-index: 1002; left: 0; top: 7%; width: 2px; height: 86%; border-radius: 3px; opacity: 0; visibility: hidden; background: linear-gradient(180deg, transparent, rgba(255,255,255,.50) 28%, #fff 50%, rgba(85,227,164,.68) 70%, transparent); box-shadow: 0 0 22px rgba(255,255,255,.32), 0 0 44px rgba(85,227,164,.14); transform: translate3d(var(--startup-panel-width),0,0); pointer-events: none; will-change: transform, opacity; }
html.startup-transition-running .startup-loader-frame { pointer-events: none; animation: startup-loader-iris 620ms cubic-bezier(.62,0,.22,1) both; }
html.startup-transition-running .startup-reveal-panel,
html.startup-transition-running .startup-reveal-edge { display:none; }
html.startup-transition-running .app-shell { animation: startup-menu-emerge 680ms cubic-bezier(.18,.78,.2,1) both; }
html.startup-transition-complete .startup-loader-frame,
html.startup-transition-complete .startup-reveal-panel,
html.startup-transition-complete .startup-reveal-edge { display: none; }

.app-shell { position: fixed; isolation: isolate; inset:0; display: grid; grid-template-columns: 218px 1fr; width: 100%; height: 100%; overflow: hidden; border: 1px solid var(--line-bright); border-radius: 10px; background: var(--bg); box-shadow: 0 24px 70px rgba(0,0,0,.46), inset 0 1px 0 rgba(255,255,255,.04); opacity: 1; transform:none; transition: opacity 220ms ease, transform 260ms ease; }
.app-background { position:absolute;z-index:0;inset:0;overflow:hidden;border-radius:inherit;background:var(--background);pointer-events:none; }
.app-background-base { position:absolute;inset:0;background:var(--app-background); }
.app-background img,.app-background video { position:absolute;inset:-2%;width:104%;height:104%;contain:strict;opacity:var(--background-media-opacity);object-fit:var(--background-media-fit);filter:blur(var(--background-media-blur));backface-visibility:hidden;transform:translateZ(0) scale(1.02);transition:opacity 180ms ease,filter 180ms ease; }
.app-background img:not([src]),.app-background video:not([src]) { display:none; }
.app-shell::before { content: ""; position: absolute; z-index: 0; inset: 0; background: radial-gradient(circle at 16% 8%, rgba(255,255,255,.055), transparent 25%), radial-gradient(circle at 92% 72%, rgba(255,255,255,.025), transparent 30%); pointer-events: none; }
.app-shell::after { content: ""; position: absolute; z-index: 30; inset: 0; border: 1px solid rgba(255,255,255,.035); border-radius: 10px; pointer-events: none; }
.window-resize-grip { position:fixed;z-index:220;right:0;bottom:0;width:32px;height:32px;cursor:nwse-resize;pointer-events:none;touch-action:none;user-select:none; }
.window-resize-grip::after { content:"";position:absolute;right:5px;bottom:5px;width:18px;height:18px;opacity:.42;pointer-events:none;background:repeating-linear-gradient(135deg,transparent 0 4px,rgba(255,255,255,.42) 4px 5px,transparent 5px 8px);clip-path:polygon(100% 0,100% 100%,0 100%);transition:opacity 150ms ease; }
.window-resize-grip:hover::after,.window-resize-grip:active::after { opacity:.78; }
.window-load-border { position: absolute; z-index: 80; inset: 0; display: block; width: 100%; height: 100%; opacity: 0; pointer-events: none; }
.window-load-border.is-loading, .window-load-border.is-loaded, .window-load-border.is-failed { opacity: 1; }
