.region-toolbar>span i { display:none }
.region-reset-button { border-color:rgba(255,255,255,.11)!important;color:#c1c5c5!important;background:rgba(25,27,29,.88)!important }
.region-reset-button:hover { border-color:rgba(255,255,255,.22)!important;color:#f3f5f5!important;background:rgba(255,255,255,.055)!important }
.region-canvas-wrap { border-color:rgba(255,255,255,.13);border-radius:10px;background:#060707;box-shadow:none }
.region-canvas-wrap canvas { opacity:.4;filter:saturate(.92) brightness(.9) }
.region-canvas-wrap canvas.has-frame { opacity:1 }
.region-canvas-wrap>em,.region-canvas-wrap>output { padding:4px 7px;border:1px solid rgba(255,255,255,.09);border-radius:5px;color:rgba(239,242,242,.68);background:rgba(8,9,9,.65);font:8px "Ubuntu",sans-serif;letter-spacing:0 }
.region-box { border-color:rgba(245,247,247,.56);background:rgba(0,0,0,.035);box-shadow:none }
.region-box:not(.is-active) { opacity:.62 }
.region-box.is-active { border-color:rgba(132,215,199,.88);background:rgba(94,189,171,.035);box-shadow:none }
.region-box b { left:5px;top:5px;padding:3px 5px;border:0;border-radius:4px;color:rgba(247,249,249,.82);background:rgba(7,8,8,.62);font:500 8px "Ubuntu",sans-serif;letter-spacing:0 }
#region-modal[data-kind="blind"] .region-box { border-color:rgba(255,255,255,.68);background:rgba(0,0,0,.82);box-shadow:inset 0 0 0 1px rgba(0,0,0,.55) }
