/* One unobtrusive caret for every scrollable menu surface. Chromium otherwise
   draws a native track and arrow buttons inside the workspace modals. */
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-track,
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-track-piece,
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-corner {
  background: transparent;
}
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-button {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  -webkit-appearance: none;
}
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-thumb {
  min-height: 42px;
  border: 3px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb,var(--muted) 42%,transparent);
  background-clip: content-box;
}
:where(.page,.nav-tabs,.studio-pane,.studio-bind-panel,.photo-grid,.photo-editor,.capture-advanced,.visual-element-panel)::-webkit-scrollbar-thumb:hover {
  background-color: color-mix(in srgb,var(--text) 58%,transparent);
}
