/* In-menu model/backend optimizer. It replaces the settings surface without
   creating a second native window, while the WebView thread stays responsive. */
.optimizer-screen { --optimizer-accent: #f3b957; position: fixed; z-index: 105; inset: 1px; display: grid; grid-template-rows: minmax(0, 1fr) auto; padding: 0; overflow: hidden; contain: layout paint style; border-radius: 9px; opacity: 0; visibility: hidden; pointer-events: none; transform: scale(1.018); background: linear-gradient(160deg, rgba(5,8,15,.985), rgba(3,5,10,.997)); transition: opacity 280ms ease, transform 440ms var(--motion), visibility 0s linear 440ms; }
.optimizer-screen:not(.is-visible), .optimizer-screen:not(.is-visible) * { animation-play-state: paused !important; }
.optimizer-screen::before { content: ""; position: absolute; inset: 0; opacity: .25; pointer-events: none; background-image: linear-gradient(rgba(255,255,255,.018) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.015) 1px, transparent 1px); background-size: 38px 38px; mask-image: radial-gradient(circle at center, #000, transparent 82%); }
.optimizer-screen::after { content: ""; position: absolute; inset: 0; border: 1px solid rgba(255,255,255,.07); border-radius: inherit; box-shadow: inset 0 0 45px 4px rgba(0,0,0,.84); pointer-events: none; }
.optimizer-screen.is-visible { opacity: 1; visibility: visible; pointer-events: auto; transform: scale(1); transition-delay: 0s; }
/* The optimizer is effectively opaque. Keeping the complete settings tree
   blurred underneath it forces Chromium to retain and continuously composite
   another full-window surface for the whole (large) menu. Do not rasterize
   that hidden surface while a model is being built. */
html.optimizer-open body > .app-shell { visibility: hidden; opacity: 0; filter: none; transform: none; pointer-events: none; }
.app-shell { filter: none; transition: opacity 220ms ease, transform 430ms var(--motion), filter 330ms ease; }
.optimizer-aurora { position: absolute; inset: -25%; opacity: .7; pointer-events: none; background: radial-gradient(circle at 14% 46%, rgba(65,121,226,.14), transparent 24%), radial-gradient(circle at 82% 26%, rgba(204,63,111,.10), transparent 24%), radial-gradient(circle at 52% 80%, rgba(57,201,169,.09), transparent 25%); animation: optimizer-aurora 10s ease-in-out infinite alternate; }
.optimizer-screen.is-class-mapping-open .optimizer-aurora,
.optimizer-screen.is-class-mapping-open .optimizer-stage *,
.optimizer-screen.is-class-mapping-open > .optimizer-header *,
.optimizer-screen.is-class-mapping-open > .optimizer-footer * { animation-play-state: paused !important; }

