html[data-ambient-load="medium"] { --ambient-color:#55bde2;--ambient-grid-size:42px;--ambient-grid-opacity:.33; }
html[data-ambient-load="high"] { --ambient-color:#e6aa58;--ambient-grid-size:38px;--ambient-grid-opacity:.35; }
html.ambient-busy { --ambient-color:#8d82ed;--ambient-grid-size:34px;--ambient-grid-opacity:.37; }
html.ambient-training { --ambient-color:#61d99b;--ambient-grid-size:36px;--ambient-grid-opacity:.35; }
html.ambient-error { --ambient-color:#ef5d78;--ambient-grid-opacity:.36; }
