.ambient-grid::before { content:"";position:absolute;inset:0;background:radial-gradient(circle at 20% 10%,color-mix(in srgb,var(--ambient-color) 18%,transparent),transparent 34%),radial-gradient(circle at 82% 74%,color-mix(in srgb,var(--ambient-color) 12%,transparent),transparent 38%);opacity:.8; }
