/* The Neural page owns a persistent lower dock instead of placing the Data
   Studio launcher in the scrolling masonry flow. */
.workspace>.data-studio-launcher { position:absolute;z-index:5;left:16px;right:16px;bottom:0;display:none;min-height:88px;margin:0;padding:14px 16px;border-bottom:0;border-radius:16px 16px 0 0;background:radial-gradient(circle at 12% 50%,rgba(84,209,229,.095),transparent 30%),linear-gradient(145deg,rgba(17,20,23,.88),rgba(8,11,14,.94));-webkit-backdrop-filter:blur(16px) saturate(1.05);backdrop-filter:blur(16px) saturate(1.05);box-shadow:0 -16px 42px rgba(0,0,0,.28),inset 0 1px rgba(255,255,255,.045); }
html[data-ambient-page="neural"] .workspace>.data-studio-launcher { display:grid;animation:data-studio-dock-in 190ms cubic-bezier(.2,.8,.2,1) both; }
.page[data-settings-page="neural"] { padding-bottom:var(--data-studio-dock-height); }
@keyframes data-studio-dock-in { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:none} }

/* Compact bind entry points and one shared editor dialog. */
.bind-editor[hidden] { display:none; }
.bind-manager-launch { position:relative;display:flex;align-items:center;justify-content:space-between;gap:14px;width:100%;min-height:48px;padding:0 15px;border:1px solid rgba(255,255,255,.12);border-radius:11px;color:#edf0ef;background:linear-gradient(145deg,rgba(27,29,30,.72),rgba(12,14,15,.78));box-shadow:inset 0 1px rgba(255,255,255,.04),0 8px 22px rgba(0,0,0,.16);cursor:pointer;text-align:left;transition:border-color 150ms ease,background 150ms ease,box-shadow 150ms ease; }
.bind-manager-launch>span { display:grid;gap:3px; }
.bind-manager-launch strong { font-size:13px;font-weight:700; }
.bind-manager-launch small { color:#858d8d;font-size:10px;font-weight:500; }
.bind-manager-launch-icon { display:grid;width:25px;height:25px;flex:0 0 25px;place-items:center;border:1px solid rgba(255,255,255,.11);border-radius:8px;color:#9da5a5;background:rgba(255,255,255,.025); }
.bind-manager-launch-icon .lucide-icon { width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round; }
.bind-manager-launch:hover { border-color:rgba(255,255,255,.24);background:linear-gradient(145deg,rgba(34,36,37,.78),rgba(15,17,18,.84));box-shadow:inset 0 1px rgba(255,255,255,.055),0 9px 24px rgba(0,0,0,.2); }
.bind-manager-launch:hover>.bind-manager-launch-icon { border-color:rgba(255,255,255,.2); }
.bind-manager-launch.is-capturing { border-color:rgba(84,212,188,.38);box-shadow:inset 0 1px rgba(255,255,255,.05),0 0 20px rgba(84,212,188,.08); }
.bind-manager-launch[hidden] { display:none; }
.setting-divider:has(+ .bind-manager-launch[hidden]) { display:none; }
.data-studio-body:has(>.studio-bind-panel #dataset-binds-open[hidden]) { grid-template-columns:minmax(0,1fr); }
.studio-bind-panel:has(#dataset-binds-open[hidden]) { display:none; }

.hotkey-root-menu { position:fixed;z-index:460;display:grid;width:min(236px,calc(100vw - 24px));max-height:calc(100vh - 20px);padding:8px;overflow-x:hidden;overflow-y:auto;border:1px solid rgba(255,255,255,.14);border-radius:15px;color:#e9ebed;background:radial-gradient(circle at 12% -8%,rgba(255,255,255,.075),transparent 42%),linear-gradient(150deg,rgba(29,30,33,.99),rgba(14,15,18,.995));box-shadow:0 24px 68px rgba(0,0,0,.62),inset 0 1px rgba(255,255,255,.055);opacity:0;transform:translateY(6px) scale(.975);transition:opacity 145ms ease,transform 185ms cubic-bezier(.2,.8,.2,1); }
.hotkey-root-menu[hidden] { display:none; }
.hotkey-root-menu.is-open { opacity:1;transform:none; }
.hotkey-root-menu>header { display:grid;gap:3px;padding:8px 10px 10px;border-bottom:1px solid rgba(255,255,255,.065); }
.hotkey-root-menu>header small { color:#777f88;font-size:9px;letter-spacing:.11em; }
.hotkey-root-menu>header strong { overflow:hidden;font-size:13px;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-root-menu>.hotkey-menu-notice { margin:6px 0 0;padding:10px 10px 5px;border-top:1px solid var(--line-soft,rgba(255,255,255,.065));color:var(--muted,#a5abb2);font-size:10px;line-height:1.4;white-space:nowrap; }
.hotkey-root-menu .lucide-icon,.hotkey-picker .lucide-icon,.hotkey-editor-popover .lucide-icon { display:block;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round; }
.hotkey-root-menu>button { position:relative;display:flex;align-items:center;width:100%;min-width:0;border:0;border-radius:10px;color:#b5bac0;background:transparent;cursor:pointer;text-align:left;transition:color 120ms ease,background 120ms ease; }
.hotkey-root-menu>button[hidden] { display:none; }
.hotkey-root-menu>button:hover,.hotkey-root-menu>button:focus-visible,.hotkey-root-menu>button.is-open { color:#f4f5f6;background:rgba(255,255,255,.065); }
.hotkey-axis-mode { display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:50px;margin:2px 0;padding:7px 10px;border-top:1px solid rgba(255,255,255,.06);border-bottom:1px solid rgba(255,255,255,.06);color:#dfe2e4; }
.hotkey-axis-mode[hidden] { display:none; }
.hotkey-axis-mode>span { display:flex;align-items:center;min-width:0;gap:9px; }
.hotkey-axis-mode>span>.lucide-icon { width:18px;height:18px;flex:0 0 18px;color:#9299a1; }
.hotkey-axis-mode>span>span { display:grid;min-width:0;gap:2px; }
.hotkey-axis-mode strong { font-size:11px;font-weight:650; }
.hotkey-axis-mode small { color:#7e858d;font-size:8px; }
.hotkey-axis-mode .toggle { --toggle-width:38px;--toggle-height:22px;--toggle-thumb-size:14px;--toggle-inset:4px;--toggle-travel:16px; }
.hotkey-root-current { gap:10px;min-height:58px;margin:6px 0;padding:7px 30px 7px 10px; }
.hotkey-root-current:hover,.hotkey-root-current:focus-visible,.hotkey-root-current.is-open { background:transparent!important; }
.hotkey-root-current::before { content:"";position:absolute;z-index:0;inset:0;border:1px solid rgba(255,255,255,.11);border-radius:10px;background:linear-gradient(100deg,rgba(255,255,255,.085),rgba(255,255,255,.035));box-shadow:inset 0 1px rgba(255,255,255,.055),0 8px 22px rgba(0,0,0,.16);opacity:0;transition:opacity 135ms ease;pointer-events:none; }
.hotkey-root-current::after { content:"";position:absolute;z-index:0;right:0;top:18px;width:2px;height:22px;border-radius:2px;background:#f5f6f7;box-shadow:0 0 10px rgba(255,255,255,.42);opacity:0;transition:opacity 135ms ease;pointer-events:none; }
.hotkey-root-current:hover::before,.hotkey-root-current:hover::after,.hotkey-root-current:focus-visible::before,.hotkey-root-current:focus-visible::after,.hotkey-root-current.is-open::before,.hotkey-root-current.is-open::after { opacity:1; }
.hotkey-root-current>* { position:relative;z-index:1; }
.hotkey-root-current>svg:first-child { width:21px;height:21px;flex:0 0 21px;color:#b4bac1; }
.hotkey-root-current>span { display:grid;min-width:0;gap:3px; }
.hotkey-root-current>span small { color:#757d86;font-size:9px; }
.hotkey-root-current>span strong { overflow:hidden;color:inherit;font-size:13px;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-root-current>.hotkey-chevron { position:absolute;right:10px;top:50%;width:16px;height:16px;color:#8c939b;transform:translateY(-50%); }
.hotkey-root-action { gap:11px;min-height:42px;padding:0 10px; }
.hotkey-root-action>svg { width:19px;height:19px;flex:0 0 19px;color:#a7adb3; }
.hotkey-root-action>span { font-size:12px;font-weight:600; }
.hotkey-root-calibration { margin-bottom:2px; }
.hotkey-root-calibration.is-active { color:var(--enabled)!important;background:color-mix(in srgb,var(--enabled) 9%,transparent)!important; }
.hotkey-root-calibration.is-active>svg { color:var(--enabled); }
.hotkey-root-reset { margin-top:5px;border-top:1px solid rgba(255,255,255,.065)!important;border-radius:0 0 9px 9px!important;color:#c27b80!important; }
.hotkey-root-reset:disabled { opacity:.34;cursor:default;pointer-events:none; }
.hotkey-root-help { display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:42px;margin-top:4px;padding:6px 7px 0 10px;border-top:1px solid rgba(255,255,255,.065); }
.hotkey-root-help[hidden] { display:none; }
.hotkey-root-help>strong { overflow:hidden;color:#dfe2e4;font-size:12px;font-weight:600;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-root-help>button { min-width:82px;height:29px;padding:0 11px;border:1px solid;border-radius:8px;font-family:inherit;font-size:10px;font-weight:600;line-height:1;cursor:pointer;transition:border-color 120ms ease,color 120ms ease,background 120ms ease,transform 120ms ease; }
.hotkey-root-help>button:active { transform:translateY(1px); }

.hotkey-picker { --hotkey-picker-y:0px;position:fixed;z-index:461;width:min(218px,calc(100vw - 24px));padding:4px;overflow:hidden;border:1px solid rgba(255,255,255,.14);border-radius:13px;color:#e9ebed;background:radial-gradient(circle at 12% -8%,rgba(255,255,255,.07),transparent 44%),linear-gradient(150deg,rgba(28,29,32,.995),rgba(13,14,17,.998));box-shadow:0 22px 62px rgba(0,0,0,.62),inset 0 1px rgba(255,255,255,.05);opacity:0;transform:translateX(-6px) scale(.98);transition:opacity 145ms ease,transform 190ms cubic-bezier(.2,.8,.2,1); }
.hotkey-picker[hidden] { display:none; }
.hotkey-picker.is-open { opacity:1;transform:none; }
.hotkey-picker>div { position:relative;z-index:1;display:grid; }
.hotkey-picker-glass { position:absolute;z-index:0;left:4px;right:4px;top:4px;height:44px;border:1px solid rgba(255,255,255,.11);border-radius:10px;background:linear-gradient(100deg,rgba(255,255,255,.085),rgba(255,255,255,.035));box-shadow:inset 0 1px rgba(255,255,255,.055),0 8px 22px rgba(0,0,0,.16);opacity:0;transform:translateY(var(--hotkey-picker-y));transition:transform 265ms cubic-bezier(.2,.78,.18,1),opacity 130ms ease;pointer-events:none; }
.hotkey-picker.has-selection .hotkey-picker-glass { opacity:1; }
.hotkey-picker-glass::after { content:"";position:absolute;right:-1px;top:10px;width:2px;height:22px;border-radius:2px;background:#f5f6f7;box-shadow:0 0 10px rgba(255,255,255,.42); }
.hotkey-picker button { position:relative;z-index:1;display:flex;align-items:center;gap:10px;width:100%;height:44px;padding:0 10px;border:0;border-radius:10px;color:#aeb4bb;background:transparent;text-align:left;cursor:pointer;transition:color 135ms ease; }
.hotkey-picker button:hover,.hotkey-picker button:focus-visible,.hotkey-picker button.is-glass-active { color:#f5f6f7; }
.hotkey-picker button>svg { width:18px;height:18px;flex:0 0 18px;color:#aeb4bb; }
.hotkey-picker button>span { display:grid;min-width:0;gap:2px; }
.hotkey-picker button strong { overflow:hidden;font-size:10px;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-picker button small { color:#7b838c;font-size:8px; }
.hotkey-picker .hotkey-picker-add { margin-top:0;border-top:0;border-radius:9px; }
.hotkey-picker button + .hotkey-picker-add { margin-top:3px;border-top:1px solid rgba(255,255,255,.06);border-radius:0 0 9px 9px; }

.hotkey-editor-popover { --hotkey-detail-shift:-7px;position:fixed;z-index:462;display:grid;width:min(370px,calc(100vw - 24px));gap:0;overflow:hidden;border:1px solid rgba(255,255,255,.15);border-radius:14px;color:#eceeef;background:radial-gradient(circle at 18% -12%,rgba(255,255,255,.075),transparent 42%),linear-gradient(150deg,rgba(30,31,34,.99),rgba(15,16,19,.998));box-shadow:0 26px 72px rgba(0,0,0,.65),inset 0 1px rgba(255,255,255,.055);opacity:0;transform:translateX(var(--hotkey-detail-shift)) scale(.98);transform-origin:left center;transition:opacity 145ms ease,transform 185ms cubic-bezier(.2,.8,.2,1); }
.hotkey-editor-popover:has(.hotkey-value-multi.is-open) { overflow:visible; }
.hotkey-editor-popover[hidden] { display:none; }
.hotkey-editor-popover.is-open { opacity:1;transform:none; }
.hotkey-editor-popover>header { display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:52px;padding:0 11px 0 14px;border-bottom:1px solid rgba(255,255,255,.075); }
.hotkey-editor-popover>header>span { display:grid;min-width:0;gap:4px; }
.hotkey-editor-popover>header small { color:#7e858e;font-size:9px;letter-spacing:.11em; }
.hotkey-editor-popover>header strong { overflow:hidden;font-size:15px;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-editor-close { display:grid;width:28px;height:28px;padding:0;place-items:center;border:1px solid rgba(255,255,255,.1);border-radius:8px;color:#a5abb2;background:rgba(255,255,255,.025); }
.hotkey-editor-close>svg { width:15px;height:15px; }
.hotkey-key-capture,.hotkey-mode,.hotkey-value,.hotkey-suppression,.hotkey-visible { display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:50px;margin:0 11px;padding:0 4px;border:0;border-bottom:1px solid rgba(255,255,255,.065);color:#dfe2e4;background:transparent;text-align:left; }
.hotkey-key-capture>*,.hotkey-mode>*,.hotkey-value>*,.hotkey-suppression>*,.hotkey-visible>* { min-width:0; }
.hotkey-key-capture>span,.hotkey-mode>span,.hotkey-value>span,.hotkey-suppression>span,.hotkey-visible>span { display:flex;align-items:center;gap:8px; }
.hotkey-key-capture span>svg,.hotkey-mode span>svg,.hotkey-value span>svg,.hotkey-suppression span>svg,.hotkey-visible span>svg { width:18px;height:18px;flex:0 0 18px;color:#9299a1; }
.hotkey-key-capture strong,.hotkey-mode strong,.hotkey-value strong,.hotkey-suppression strong,.hotkey-visible strong { font-size:12px;font-weight:650; }
.hotkey-key-capture>b { display:grid;place-items:center;min-width:84px;max-width:190px;height:34px;padding:0 10px;overflow:hidden;border:1px solid rgba(255,255,255,.11);border-radius:9px;color:#f2f3f4;background:rgba(255,255,255,.04);font-size:11px;line-height:1;text-align:center;text-overflow:ellipsis;white-space:nowrap; }
.hotkey-key-capture.is-listening>b { border-color:rgba(255,255,255,.38);box-shadow:0 0 0 3px rgba(255,255,255,.055);animation:hotkey-listening 900ms ease-in-out infinite alternate; }
.key-waiting-dots { display:inline-flex;min-width:30px;height:14px;align-items:center;justify-content:center;gap:4px;color:inherit; }
.key-waiting-dots>i { display:block;width:4px;height:4px;border-radius:50%;background:currentColor;opacity:.42;animation:key-waiting-dot 720ms ease-in-out infinite alternate; }
.key-waiting-dots>i:nth-child(2) { animation-delay:120ms; }
.key-waiting-dots>i:nth-child(3) { animation-delay:240ms; }
@keyframes key-waiting-dot { 0%,20%{opacity:.4;transform:translateY(2px)} 80%,100%{opacity:1;transform:translateY(-2px)} }
.hotkey-mode>div { --hotkey-mode-index:0;--hotkey-mode-count:3;position:relative;display:grid;width:246px;grid-template-columns:repeat(var(--hotkey-mode-count),minmax(0,1fr));padding:3px;border:1px solid rgba(255,255,255,.09);border-radius:10px;background:rgba(3,4,6,.32); }
.hotkey-mode>div.hotkey-mode-hold { --hotkey-mode-index:1; }
.hotkey-mode>div>i { position:absolute;left:3px;top:3px;width:calc((100% - 6px) / var(--hotkey-mode-count));height:28px;border-radius:7px;background:#ededee;box-shadow:0 4px 12px rgba(0,0,0,.22),inset 0 1px rgba(255,255,255,.7);transform:translateX(calc(var(--hotkey-mode-index) * 100%));transition:transform 260ms cubic-bezier(.2,.78,.18,1);pointer-events:none; }
.hotkey-mode button { position:relative;z-index:1;min-width:0;width:auto;height:28px;padding:0 3px;overflow:hidden;border:0;border-radius:7px;color:#777e87;background:transparent;font-size:9px;text-overflow:ellipsis;white-space:nowrap;transition:color 180ms ease; }
.hotkey-mode button.is-active { color:#17181a;background:transparent;box-shadow:none; }
.hotkey-mode button[hidden],.hotkey-mode.is-fixed { display:none; }
.hotkey-value>input,.hotkey-value>select,.hotkey-value>.custom-select,.hotkey-value>.hotkey-value-multi { width:146px;min-width:0; }
.hotkey-value>.hotkey-value-multi .choice-dropdown-trigger { height:34px;padding:0 9px;font-size:10px; }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu { min-width:128px;right:0;left:auto; }
.hotkey-value>.hotkey-value-multi .choice-dropdown-trigger,
.hotkey-value>.hotkey-value-multi.is-open .choice-dropdown-trigger { border-color:rgba(255,255,255,.15);color:#eceeef;background:linear-gradient(180deg,rgba(27,28,30,.99),rgba(14,15,17,.99));box-shadow:inset 0 1px rgba(255,255,255,.05); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-trigger:hover,
.hotkey-value>.hotkey-value-multi.is-open .choice-dropdown-trigger:hover { border-color:rgba(255,255,255,.30);background:linear-gradient(180deg,rgba(34,35,38,.99),rgba(18,19,21,.99));box-shadow:0 0 0 3px rgba(255,255,255,.035),inset 0 1px rgba(255,255,255,.065); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu { border-color:rgba(255,255,255,.13);background:linear-gradient(155deg,rgba(27,28,31,.995),rgba(12,13,15,.995));box-shadow:0 18px 38px rgba(0,0,0,.64),inset 0 1px rgba(255,255,255,.06); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button:hover { color:#f5f6f7;background:rgba(255,255,255,.06); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button:active { background:rgba(255,255,255,.09); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button.is-active { color:#f4f5f6;background:rgba(255,255,255,.075); }
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button.is-active i { border-color:#e9ebed;background:#e9ebed;box-shadow:0 0 11px rgba(255,255,255,.15); }
.hotkey-value>.custom-select[hidden],.hotkey-value>input[hidden] { display:none; }
.hotkey-value>input { height:34px;text-align:right; }
.hotkey-value.is-command { display:none; }
.hotkey-value-warning { display:flex;align-items:flex-start;gap:8px;margin:0 11px;padding:9px 4px 10px;color:#d6a85e;border-bottom:1px solid rgba(214,168,94,.16);font-size:9px;line-height:1.45; }
.hotkey-value-warning[hidden] { display:none!important; }
.hotkey-value-warning.is-error { color:var(--danger,#d87579);border-bottom-color:color-mix(in srgb,var(--danger,#d87579) 20%,transparent); }
.hotkey-value-warning .lucide-icon { width:15px;height:15px;flex:0 0 15px;margin-top:1px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round; }
.hotkey-value-warning span { min-width:0; }
.hotkey-suppression>span,.hotkey-visible>span { display:grid;grid-template-columns:18px auto;gap:1px 8px; }
.hotkey-suppression>span svg,.hotkey-visible>span svg { grid-row:1/3; }
.hotkey-suppression small,.hotkey-visible small { color:#7e858d;font-size:9px; }
.hotkey-visible-toggle { --toggle-width:42px;--toggle-height:24px;--toggle-thumb-size:16px;--toggle-inset:4px;--toggle-travel:18px; }
.hotkey-editor-popover>footer { display:grid;gap:6px;padding:8px 11px 11px; }
.hotkey-editor-popover>footer button { display:flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 11px;border:1px solid rgba(255,255,255,.1);border-radius:8px;color:#aeb4ba;background:rgba(255,255,255,.035);font-size:9px; }
.hotkey-editor-popover>footer button>svg { width:13px;height:13px; }
.hotkey-editor-popover .hotkey-delete { color:#bf777b; }
.hotkey-editor-popover .hotkey-delete[hidden] { display:none; }
.hotkey-editor-popover>footer:has(.hotkey-delete[hidden]) { display:none; }
@keyframes hotkey-listening { from{filter:brightness(.86)}to{filter:brightness(1.18)} }

/* App-owned color picker. It follows the bind popover geometry while every
   material color comes from the currently resolved user/reseller palette. */
.naim-color-picker { --picker-hue:0;--picker-saturation:0;--picker-value:100;--hotkey-detail-shift:-7px;z-index:10060;width:min(330px,calc(100vw - 24px));border-color:var(--line-bright);color:var(--text);background:radial-gradient(circle at 18% -12%,color-mix(in srgb,var(--text) 7%,transparent),transparent 42%),linear-gradient(150deg,color-mix(in srgb,var(--card) 96%,var(--background)),color-mix(in srgb,var(--background) 98%,var(--card)));box-shadow:0 26px 72px rgba(0,0,0,.52),inset 0 1px color-mix(in srgb,var(--text) 6%,transparent);transform-origin:left center; }
.naim-color-picker.is-left { --hotkey-detail-shift:7px;transform-origin:right center; }
.naim-color-picker>header { border-bottom-color:var(--line-soft); }
.naim-color-picker>header small { color:color-mix(in srgb,var(--accent) 72%,var(--muted));font-weight:750; }
.naim-color-picker>header strong { color:var(--text); }
.naim-color-picker .hotkey-editor-close { border-color:var(--line);color:var(--muted);background:color-mix(in srgb,var(--control) 80%,transparent);cursor:pointer;transition:color 120ms ease,border-color 120ms ease,background 120ms ease,transform 120ms ease; }
.naim-color-picker .hotkey-editor-close:hover,.naim-color-picker .hotkey-editor-close:focus-visible { border-color:color-mix(in srgb,var(--accent) 32%,var(--line));color:var(--text);background:color-mix(in srgb,var(--accent) 8%,var(--control));outline:0; }
.naim-color-picker .hotkey-editor-close:active { transform:scale(.94); }
.naim-color-picker-body { display:grid;gap:11px;padding:12px 13px 11px; }
.naim-color-saturation { position:relative;height:148px;overflow:hidden;border:1px solid var(--line-bright);border-radius:10px;background:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,hsl(var(--picker-hue) 100% 50%));box-shadow:inset 0 1px color-mix(in srgb,var(--text) 8%,transparent),inset 0 -18px 30px rgba(0,0,0,.12);cursor:crosshair;touch-action:none;outline:0; }
