/* Mouse sensitivity calibration */
.mouse-calibration-summary{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:center;gap:13px;padding:13px 0 0}
.mouse-calibration-summary>span:nth-child(2){display:grid;gap:2px;min-width:0}.mouse-calibration-summary small{color:#777e87;font:700 8px Consolas,monospace;letter-spacing:.1em}.mouse-calibration-summary strong{color:#eee;font-size:14px}.mouse-calibration-summary em{overflow:hidden;color:#81878f;font-size:10px;font-style:normal;white-space:nowrap;text-overflow:ellipsis}
.mouse-calibration-orbit{position:relative;width:40px;height:40px;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:linear-gradient(145deg,rgba(255,255,255,.045),rgba(255,255,255,.012));box-shadow:inset 0 1px rgba(255,255,255,.05)}
.mouse-calibration-orbit::before{content:"";position:absolute;inset:10px;border:1px solid rgba(119,210,191,.55);border-radius:50%}.mouse-calibration-orbit::after{content:"";position:absolute;left:18px;top:18px;width:4px;height:4px;border-radius:50%;background:#dfe6e5;box-shadow:0 0 9px rgba(119,210,191,.55)}.mouse-calibration-orbit i{position:absolute;left:7px;top:19px;width:5px;height:1px;background:#7ed2c0}.mouse-calibration-orbit i:last-child{left:auto;right:7px}
.mouse-calibration-shield{--calibration-accent:#73d2bd;position:fixed;z-index:990;inset:0;display:grid;place-items:center;padding:22px;border-radius:10px;opacity:0;visibility:hidden;background:radial-gradient(circle at 50% 39%,rgba(115,210,189,.045),transparent 32%),rgba(4,5,7,.78);-webkit-backdrop-filter:blur(14px) brightness(.42) saturate(.35);backdrop-filter:blur(14px) brightness(.42) saturate(.35);transition:opacity 210ms ease,visibility 0s linear 210ms}
.mouse-calibration-shield[hidden]{display:none}.mouse-calibration-shield.is-visible{opacity:1;visibility:visible;transition-delay:0s}.mouse-calibration-shield::before{content:"";position:absolute;inset:0;opacity:.18;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:32px 32px;mask-image:radial-gradient(circle at 50% 45%,#000,transparent 68%);pointer-events:none}
.mouse-calibration-panel{position:relative;display:grid;justify-items:center;width:min(430px,calc(100vw - 38px));padding:22px 27px 23px;overflow:hidden;border:1px solid rgba(255,255,255,.14);border-radius:22px;color:#f2f3f4;background:radial-gradient(circle at 50% 0,rgba(115,210,189,.055),transparent 36%),linear-gradient(150deg,rgba(29,30,33,.99),rgba(14,15,18,.995));box-shadow:inset 0 1px rgba(255,255,255,.055),0 34px 100px rgba(0,0,0,.66),0 0 50px rgba(115,210,189,.035);opacity:0;transform:translateY(14px) scale(.968);transition:opacity 180ms ease,transform 300ms cubic-bezier(.18,.84,.2,1)}
.mouse-calibration-shield.is-visible .mouse-calibration-panel{opacity:1;transform:none}.mouse-calibration-visual{position:relative;display:grid;width:106px;height:106px;margin:-2px 0 7px;place-items:center}.mouse-calibration-visual>span{position:absolute;inset:17px;border:1px solid rgba(115,210,189,.18);border-radius:22px;background:radial-gradient(circle,rgba(115,210,189,.085),rgba(5,6,8,.82) 70%);box-shadow:inset 0 0 27px rgba(0,0,0,.48),0 0 32px rgba(115,210,189,.07);transform:rotate(45deg);animation:calibration-halo 3.2s ease-in-out infinite}.mouse-calibration-visual>span::before,.mouse-calibration-visual>span::after{content:"";position:absolute;width:5px;height:5px;border-radius:50%;background:var(--calibration-accent);box-shadow:0 0 10px rgba(115,210,189,.42);opacity:.52}.mouse-calibration-visual>span::before{left:3px;top:3px}.mouse-calibration-visual>span::after{right:3px;bottom:3px}.mouse-calibration-visual svg{position:relative;z-index:2;width:35px;height:35px;fill:none;stroke:#d8dcde;stroke-width:1.35;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 0 8px rgba(115,210,189,.18))}.mouse-calibration-shield.is-running .mouse-calibration-visual>span{animation:calibration-running-halo 1.45s linear infinite}.mouse-calibration-shield.is-running .mouse-calibration-visual svg{stroke:var(--calibration-accent);animation:calibration-core 1.05s ease-in-out infinite}
.mouse-calibration-panel>header{display:grid;justify-items:center;gap:6px;text-align:center}.mouse-calibration-panel>header small{color:#77cbb8;font:700 9px Consolas,monospace;letter-spacing:.15em}.mouse-calibration-panel h2{margin:0;font-size:22px;letter-spacing:-.02em}.mouse-calibration-panel>header p{max-width:365px;margin:0;color:#8e949c;font-size:12px;line-height:1.48}
.mouse-calibration-readout{box-sizing:border-box;display:grid;grid-template-columns:.9fr .82fr .72fr 1.2fr .92fr;width:100%;margin-top:18px;border:1px solid rgba(255,255,255,.08);border-radius:12px;background:rgba(255,255,255,.022);overflow:hidden}.mouse-calibration-readout span{display:grid;gap:3px;min-width:0;padding:10px 8px;border-right:1px solid rgba(255,255,255,.055)}.mouse-calibration-readout span:last-child{border:0}.mouse-calibration-readout small{overflow:hidden;color:#717780;font:700 7px Consolas,monospace;letter-spacing:.08em;white-space:nowrap}.mouse-calibration-readout strong{overflow:hidden;color:#e6e8e9;font-size:10px;white-space:nowrap;text-overflow:ellipsis}
.mouse-calibration-progress-track{width:100%;height:3px;margin-top:9px;overflow:hidden;border-radius:9px;background:rgba(255,255,255,.055)}.mouse-calibration-progress-track i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#5b9d90,var(--calibration-accent));box-shadow:0 0 10px rgba(115,210,189,.34);transition:width 160ms linear}
