.mouse-calibration-cancel-hint{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;margin:10px 0 0;color:#7e858d;font-size:9px;line-height:1.35;text-align:center}.mouse-calibration-cancel-hint>svg{width:13px;height:13px;flex:0 0 13px;fill:none;stroke:#9a7478;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.mouse-calibration-cancel-hint kbd{padding:3px 6px;border:1px solid rgba(255,255,255,.13);border-radius:6px;color:#d8dbde;background:rgba(255,255,255,.04);font:700 8px Ubuntu,"Segoe UI",sans-serif;box-shadow:0 1px 0 rgba(255,255,255,.04)}
.mouse-calibration-actions{display:grid;grid-template-columns:1fr;gap:9px;width:100%;margin-top:14px}.mouse-calibration-actions button{min-height:40px;border:1px solid rgba(255,255,255,.11);border-radius:10px;color:#bbc0c7;background:rgba(255,255,255,.035);cursor:pointer;font-size:11px;font-weight:650;transition:transform 120ms ease,border-color 120ms ease,background 120ms ease,color 120ms ease}.mouse-calibration-actions button:hover{border-color:rgba(255,255,255,.23);color:#f5f6f7;background:rgba(255,255,255,.065)}.mouse-calibration-actions button:active{transform:scale(.985)}
@keyframes calibration-halo{0%,100%{opacity:.68;transform:rotate(45deg) scale(.95)}50%{opacity:1;transform:rotate(45deg) scale(1.025)}}@keyframes calibration-running-halo{to{transform:rotate(405deg)}}@keyframes calibration-core{50%{opacity:.72;transform:scale(.94)}}
html[data-theme="light"] .mouse-calibration-summary strong{color:var(--text)}html[data-theme="light"] .mouse-calibration-shield{background:radial-gradient(circle at 50% 39%,rgba(28,119,101,.035),transparent 32%),rgba(222,226,232,.78);-webkit-backdrop-filter:blur(14px) brightness(.94) saturate(.65);backdrop-filter:blur(14px) brightness(.94) saturate(.65)}html[data-theme="light"] .mouse-calibration-panel{color:var(--text);border-color:var(--line);background:radial-gradient(circle at 50% 0,#fff,transparent 38%),linear-gradient(150deg,rgba(250,251,252,.995),rgba(226,229,234,.995));box-shadow:inset 0 1px #fff,0 34px 88px rgba(38,45,57,.28)}html[data-theme="light"] .mouse-calibration-panel>header p,html[data-theme="light"] .mouse-calibration-status,html[data-theme="light"] .mouse-calibration-key-capture small,html[data-theme="light"] .mouse-calibration-cancel-hint{color:var(--muted)}html[data-theme="light"] .mouse-calibration-readout,html[data-theme="light"] .mouse-calibration-key-capture{border-color:var(--line);background:rgba(255,255,255,.48)}html[data-theme="light"] .mouse-calibration-readout strong,html[data-theme="light"] .mouse-calibration-key-capture strong,html[data-theme="light"] .mouse-calibration-cancel-hint kbd{color:var(--text)}html[data-theme="light"] .mouse-calibration-actions button{border-color:var(--line);color:var(--muted);background:rgba(255,255,255,.55)}
