/* Control palette: lift interactive surfaces out of the near-black card
   shadows and keep selects, their menus and range tracks on one graphite tier. */
:root {
  --range-surface-top: #2b2c30;
  --range-surface-bottom: #222327;
  --range-fill: rgba(255,255,255,.13);
  --range-rest: rgba(255,255,255,.022);
  --select-surface-top: #2d2e32;
  --select-surface-bottom: #232428;
  --select-hover-top: #34353a;
  --select-hover-bottom: #292a2f;
  --select-menu-top: #2a2b2f;
  --select-menu-bottom: #202125;
  --select-option-hover: rgba(255,255,255,.075);
  --select-option-active: rgba(255,255,255,.105);
}

.range-row {
  border-color: rgba(255,255,255,.13);
  background: linear-gradient(180deg, var(--range-surface-top), var(--range-surface-bottom));
  box-shadow: inset 0 1px rgba(255,255,255,.05), inset 0 -1px rgba(0,0,0,.26), 0 5px 14px rgba(0,0,0,.10);
}

input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, var(--range-fill) 0 var(--fill), var(--range-rest) var(--fill) 100%);
}

.range-row.napi-motion.is-napi-hot {
  border-color: rgba(255,255,255,.20);
  background: linear-gradient(180deg, #313237, #27282c);
  box-shadow: inset 0 1px rgba(255,255,255,.07), inset 0 -1px rgba(0,0,0,.24), 0 7px 18px rgba(0,0,0,.15);
}

.choice-dropdown-trigger,
.custom-select-button,
.bind-actions .custom-select-button,
.hotkey-value>.hotkey-value-multi .choice-dropdown-trigger,
.hotkey-value>.hotkey-value-multi.is-open .choice-dropdown-trigger,
select {
  border-color: rgba(255,255,255,.135) !important;
  color: #eceef0 !important;
  background-color: var(--select-surface-bottom) !important;
  background-image: linear-gradient(180deg, var(--select-surface-top), var(--select-surface-bottom)) !important;
  box-shadow: inset 0 1px rgba(255,255,255,.055), inset 0 -1px rgba(0,0,0,.20), 0 6px 16px rgba(0,0,0,.13) !important;
}

.choice-dropdown-trigger:hover,
.custom-select-button:hover,
.bind-actions .custom-select-button:hover,
.hotkey-value>.hotkey-value-multi .choice-dropdown-trigger:hover,
.hotkey-value>.hotkey-value-multi.is-open .choice-dropdown-trigger:hover,
select:hover {
  border-color: rgba(255,255,255,.23) !important;
  background-color: var(--select-hover-bottom) !important;
  background-image: linear-gradient(180deg, var(--select-hover-top), var(--select-hover-bottom)) !important;
  box-shadow: inset 0 1px rgba(255,255,255,.075), 0 8px 20px rgba(0,0,0,.16) !important;
}

.choice-dropdown.is-open .choice-dropdown-trigger,
.custom-select.is-open .custom-select-button {
  border-color: rgba(255,255,255,.27) !important;
  background: linear-gradient(180deg, var(--select-hover-top), var(--select-hover-bottom)) !important;
  box-shadow: inset 0 1px rgba(255,255,255,.075), 0 0 0 3px rgba(255,255,255,.035), 0 9px 22px rgba(0,0,0,.18) !important;
}

.choice-dropdown-menu,
.custom-select-menu,
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu {
  border-color: rgba(255,255,255,.15) !important;
  background: linear-gradient(155deg, var(--select-menu-top), var(--select-menu-bottom)) var(--background) !important;
  box-shadow: 0 20px 50px rgba(0,0,0,.48), inset 0 1px rgba(255,255,255,.06) !important;
}

.choice-dropdown-menu button:hover,
.custom-select-option:hover,
.custom-select-option:focus-visible,
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button:hover {
  color: #fff !important;
  background: var(--select-option-hover) !important;
}

.choice-dropdown-menu button.is-active,
.custom-select-option.is-selected,
.hotkey-value>.hotkey-value-multi .choice-dropdown-menu button.is-active {
  color: #f6f7f8 !important;
  background: var(--select-option-active) !important;
}

.choice-dropdown-menu button i,
.custom-select-option>i {
  background: #25262a;
}

select option {
  color: #eceef0;
  background: #242529;
}

select,
select:hover {
  background-position: calc(100% - 16px) 15px, calc(100% - 11px) 15px, 0 0 !important;
  background-size: 5px 5px, 5px 5px, 100% 100% !important;
  background-repeat: no-repeat !important;
}

select {
  background-image: linear-gradient(45deg, transparent 50%, #a3a8af 50%), linear-gradient(135deg, #a3a8af 50%, transparent 50%), linear-gradient(180deg, var(--select-surface-top), var(--select-surface-bottom)) !important;
}

select:hover {
  background-image: linear-gradient(45deg, transparent 50%, #c4c8cd 50%), linear-gradient(135deg, #c4c8cd 50%, transparent 50%), linear-gradient(180deg, var(--select-hover-top), var(--select-hover-bottom)) !important;
}

html[data-theme="light"] {
  --range-surface-top: #dfe3e8;
  --range-surface-bottom: #d2d7de;
  --range-fill: rgba(25,30,38,.105);
  --range-rest: rgba(255,255,255,.20);
  --select-surface-top: #e8ebef;
  --select-surface-bottom: #d9dee5;
  --select-hover-top: #f2f4f7;
  --select-hover-bottom: #e1e5ea;
  --select-menu-top: #eef0f3;
  --select-menu-bottom: #dfe3e8;
  --select-option-hover: rgba(15,19,27,.065);
  --select-option-active: rgba(15,19,27,.095);
}

html[data-theme="light"] .range-row {
  border-color: rgba(20,25,34,.13);
  background: linear-gradient(180deg, var(--range-surface-top), var(--range-surface-bottom));
  box-shadow: inset 0 1px rgba(255,255,255,.72), inset 0 -1px rgba(45,52,64,.08), 0 5px 13px rgba(39,46,58,.07);
}

html[data-theme="light"] .range-row.napi-motion.is-napi-hot {
  border-color: rgba(20,25,34,.20);
  background: linear-gradient(180deg, #e7eaee, #d8dde3);
  box-shadow: inset 0 1px #fff, 0 7px 17px rgba(39,46,58,.10);
}

html[data-theme="light"] input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, var(--range-fill) 0 var(--fill), var(--range-rest) var(--fill) 100%);
}

html[data-theme="light"] :is(
  .choice-dropdown-trigger,
  .custom-select-button,
  .bind-actions .custom-select-button,
  .hotkey-value>.hotkey-value-multi .choice-dropdown-trigger,
  .hotkey-value>.hotkey-value-multi.is-open .choice-dropdown-trigger,
  select
) {
  border-color: rgba(20,25,34,.13) !important;
  color: #20242a !important;
  box-shadow: inset 0 1px rgba(255,255,255,.80), inset 0 -1px rgba(45,52,64,.07), 0 6px 15px rgba(39,46,58,.07) !important;
}

html[data-theme="light"] :is(
  .choice-dropdown-menu,
  .custom-select-menu,
  .hotkey-value>.hotkey-value-multi .choice-dropdown-menu
) {
  border-color: rgba(20,25,34,.14) !important;
  box-shadow: 0 20px 50px rgba(38,45,57,.18), inset 0 1px #fff !important;
}

html[data-theme="light"] :is(.choice-dropdown-menu button, .custom-select-option) {
  color: #656c76;
}

html[data-theme="light"] select option {
  color: #20242a;
  background: #e3e7ec;
}

html[data-theme="light"] select {
  background-image: linear-gradient(45deg, transparent 50%, #6c737d 50%), linear-gradient(135deg, #6c737d 50%, transparent 50%), linear-gradient(180deg, var(--select-surface-top), var(--select-surface-bottom)) !important;
}

html[data-theme="light"] select:hover {
  background-image: linear-gradient(45deg, transparent 50%, #414851 50%), linear-gradient(135deg, #414851 50%, transparent 50%), linear-gradient(180deg, var(--select-hover-top), var(--select-hover-bottom)) !important;
}

html[data-language="zh"] {
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", "Segoe UI", sans-serif;
}

/* Shared button geometry. Some secondary actions only carried the palette
   class and therefore fell back to WebView's square native button metrics. */
body :is(.settings-button, .quiet-settings-button) {
  box-sizing: border-box;
  min-height: var(--ui-action-height);
  height: auto;
  padding: var(--ui-action-padding-block) var(--ui-action-padding-inline);
  border-radius: var(--ui-action-radius);
  font-size: var(--ui-action-font-size);
  font-weight: var(--ui-action-font-weight);
  line-height: 1.15;
  text-align: center;
}

body .quiet-settings-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line-bright);
  color: var(--text);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--control) 92%, var(--text) 8%),
    var(--control)
  );
  box-shadow: var(--control-inset), 0 7px 16px rgba(0,0,0,.14);
  cursor: pointer;
  appearance: none;
  transition: transform 120ms var(--motion), border-color 140ms ease, background 140ms ease, box-shadow 140ms ease;
}

body .quiet-settings-button:hover {
  border-color: color-mix(in srgb, var(--text) 28%, transparent);
  color: var(--text);
  background: var(--control-hover);
  box-shadow: inset 0 1px color-mix(in srgb, var(--text) 8%, transparent), 0 9px 20px rgba(0,0,0,.18);
  filter: none;
  transform: translateY(-1px);
}

body .quiet-settings-button:active {
  transform: translateY(1px) scale(.98);
}

body :is(.settings-button, .quiet-settings-button):disabled {
  opacity: .42;
  cursor: default;
  pointer-events: none;
  transform: none;
}

/* Segmented controls use the same graphite material as dropdowns and buttons. */
.app-shell .segments {
  min-height: var(--ui-segment-height);
  border-color: var(--line-bright);
  border-radius: 11px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--control) 90%, var(--text) 4%), var(--control));
}

.app-shell .segments::before {
  inset: 0 auto 0 0;
  height: auto;
  width: 50%;
  border-radius: 10px;
  background: radial-gradient(circle at 20% -35%,rgba(255,255,255,.18),transparent 58%),linear-gradient(115deg,rgba(255,255,255,.105),rgba(255,255,255,.035));
  box-shadow: inset 0 1px rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.095),0 5px 14px rgba(0,0,0,.16);
}

.app-shell #capture-source::before {
  width: 33.333333%;
}

.app-shell .segments button {
  height: calc(var(--ui-segment-height) - 2px);
  border-right-color: var(--line-soft);
  color: var(--muted);
  letter-spacing: .02em;
}

.app-shell .segments button:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--control-hover) 58%, transparent);
}

.app-shell .segments button.is-active,
.app-shell .segments button.is-active:hover {
  color: #f5f6f8;
  background: transparent;
  text-shadow: 0 1px 8px rgba(0,0,0,.55);
}

/* Capture settings belongs to the regular menu, not the cyan data-studio
   workspace. Keep its modal, header and status badge on the neutral palette. */
.capture-settings-modal {
  background: color-mix(in srgb, var(--bg) 76%, transparent);
  backdrop-filter: blur(14px) saturate(.55);
}

/* Advanced recoil editor */
.rcs-card-body { grid-template-columns:1fr 1fr; }
.rcs-mode-switch { grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:2px 0 10px;padding:4px;border:1px solid var(--line-soft);border-radius:10px;background:color-mix(in srgb,var(--control) 72%,transparent); }
.rcs-mode-switch button { min-height:32px;border:0;border-radius:7px;color:var(--muted);background:transparent;font:700 11px "Ubuntu",sans-serif;cursor:pointer;transition:color .16s ease,background .16s ease,box-shadow .16s ease; }
.rcs-mode-switch button:hover { color:var(--text); }
.rcs-mode-switch button.is-active { color:var(--text);background:var(--control-hover);box-shadow:inset 0 1px rgba(255,255,255,.04),0 4px 12px rgba(0,0,0,.12); }
.rcs-simple-settings { grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr);gap:8px; }
.rcs-simple-settings[hidden] { display:none; }
.rcs-card-body .rcs-simple-settings>.range-row { min-width:0;margin-top:0!important; }
.rcs-advanced-summary { grid-column:1/-1;grid-template-columns:minmax(0,1fr) minmax(0,1fr) max-content;align-items:center;gap:8px;padding:9px 10px;border:1px solid var(--line-soft);border-radius:9px;background:color-mix(in srgb,var(--control) 60%,transparent); }
.rcs-advanced-summary:not([hidden]) { display:grid; }
.rcs-advanced-summary>span { display:grid;gap:3px;min-width:0; }
.rcs-advanced-summary small { color:var(--muted);font:8px Consolas,monospace;letter-spacing:.09em; }
.rcs-advanced-summary strong { overflow:hidden;font-size:11px;text-overflow:ellipsis;white-space:nowrap; }
.rcs-advanced-summary .settings-button { min-height:31px;padding-inline:12px;white-space:nowrap; }
.rcs-manual-fire-row { grid-column:1/-1; }

.rcs-editor-modal { z-index:124;padding:28px;background:color-mix(in srgb,var(--bg) 78%,transparent);backdrop-filter:blur(15px) saturate(.58); }
.rcs-editor-workspace { width:min(1040px,100%);height:min(720px,100%);grid-template-rows:auto minmax(0,1fr); }
.rcs-editor-layout { display:grid;grid-template-columns:minmax(0,1fr) 272px;min-height:0; }
.rcs-editor-controls { grid-column:2;grid-row:1;display:flex;flex-direction:column;gap:12px;min-height:0;padding:14px;border-left:1px solid var(--line-soft);overflow:auto;background:linear-gradient(180deg,color-mix(in srgb,var(--control) 32%,transparent),transparent); }
.rcs-editor-controls>section { display:grid;gap:8px;padding:11px;border:1px solid var(--line-soft);border-radius:10px;background:color-mix(in srgb,var(--control) 52%,transparent); }
.rcs-editor-controls>section>small,.rcs-graph-head small { color:var(--muted);font:8px Consolas,monospace;letter-spacing:.12em; }
.rcs-editor-controls label { position:relative;display:grid;grid-template-columns:minmax(0,1fr) 70px;align-items:center;gap:8px;min-height:42px;padding-top:8px;border-top:1px solid var(--line-soft); }
.rcs-editor-controls label:first-of-type { padding-top:0;border-top:0; }
.rcs-editor-controls label>span { display:grid;gap:2px; }
.rcs-editor-controls label strong { font-size:10px; }
.rcs-editor-controls label small,.rcs-editor-controls p { color:var(--muted);font-size:8px;line-height:1.45; }
.rcs-editor-controls label input { width:70px;height:30px;padding:0 23px 0 8px;border:1px solid var(--line-bright);border-radius:7px;outline:0;color:var(--text);background:var(--control);font:700 10px Consolas,monospace;text-align:right; }
.rcs-editor-controls label input:focus { border-color:color-mix(in srgb,var(--accent) 52%,var(--line));box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 10%,transparent); }
.rcs-editor-controls label em { position:absolute;right:5px;bottom:10px;color:var(--muted);font:7px Consolas,monospace;pointer-events:none; }
.rcs-record-section p,.rcs-editor-help p { margin:0; }
