.capture-settings-workspace {
  border-color: var(--line-bright);
  border-radius: 18px;
  color: var(--text);
  background: radial-gradient(circle at 12% -8%, color-mix(in srgb, var(--text) 5%, transparent), transparent 38%), var(--bg);
  box-shadow: 0 26px 78px rgba(0,0,0,.46), inset 0 1px color-mix(in srgb, var(--text) 6%, transparent);
}

.capture-settings-workspace > header {
  min-height: 70px;
  padding-inline: 20px;
  border-color: var(--line);
  background: color-mix(in srgb, var(--card) 78%, transparent);
}

.capture-settings-workspace .workspace-back {
  width: 40px;
  height: 40px;
  border-color: var(--line-bright);
  border-radius: 11px;
  color: var(--muted);
  background: var(--control);
  box-shadow: var(--control-inset);
}

.capture-settings-workspace .workspace-back .lucide-icon { width:19px;height:19px; }

.capture-settings-workspace .workspace-back:hover {
  border-color: color-mix(in srgb, var(--text) 25%, transparent);
  color: var(--text);
  background: var(--control-hover);
  transform: translateX(-1px);
}

.capture-settings-workspace .workspace-count {
  min-width: 0;
  padding: 7px 11px;
  border: 1px solid var(--line);
  color: var(--muted);
  background: var(--control);
  font-family: "Ubuntu", sans-serif;
  font-weight: 650;
  letter-spacing: .04em;
}

.capture-settings-workspace .capture-advanced > .card {
  border-color: var(--line-bright);
  background: var(--card);
  box-shadow: var(--panel-shadow);
}

.capture-settings-workspace .capture-api-row {
  display: none !important;
}

/* Keep the desktop selector compact even when its monitor label is long. */
.capture-settings-workspace .capture-options .select-row.desktop-source-only > .custom-select {
  width: min(228px, 58%);
  min-width: 0;
  max-width: 228px;
  flex: 0 1 228px;
}

.capture-settings-workspace .capture-monitor-actions {
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 10px 0 2px;
}

.capture-settings-workspace .capture-monitor-actions > small {
  min-width: 0;
  margin-right: auto;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.3;
}

.capture-settings-workspace .capture-monitor-actions > button {
  min-width: 82px;
}

.capture-settings-workspace .capture-mode-row {
  display: grid;
  grid-template-columns: minmax(0,1fr);
  align-items: start;
  gap: 9px;
}

.capture-settings-workspace .capture-mode-row > span,
.capture-settings-workspace .capture-mode-row > .custom-select {
  width: 100%;
  min-width: 0;
  max-width: none;
}

/* Function descriptions live in one compact, reusable hover card. */
.feature-description,
.function-help-copy {
  display: none !important;
}

.card-heading.has-function-help {
  min-height: 30px;
}

.card-head.has-function-help {
  margin-bottom: 10px;
}

.nav-tabs button.has-function-help span {
  gap: 0;
}

.function-help-popover {
  --function-help-enter-x: -10px;
  --function-help-enter-y: -6px;
  position: fixed;
  z-index: 10040;
  width: min(330px, calc(100vw - 28px));
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line) 86%, white 14%);
  border-radius: 15px;
  background: color-mix(in srgb, var(--card) 96%, transparent);
  box-shadow: 0 20px 50px rgba(0, 0, 0, .46), inset 0 1px 0 rgba(255, 255, 255, .035);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  filter: blur(3px) saturate(.92);
  transform: translate3d(var(--function-help-enter-x), var(--function-help-enter-y), 0) scale(.955);
  transform-origin: 50% 0;
  transition: opacity 150ms ease, transform 230ms cubic-bezier(.16,.82,.2,1), filter 190ms ease, visibility 0s linear 230ms;
  backdrop-filter: blur(22px) saturate(115%);
  will-change: left, top, opacity, transform, filter;
}

.function-help-popover.is-visible {
  opacity: 1;
  visibility: visible;
  filter: blur(0) saturate(1);
  transform: translate3d(0, 0, 0) scale(1);
  transition-delay: 0s;
}

.function-help-media {
  position: relative;
  height: 128px;
  overflow: hidden;
  border-bottom: 1px solid var(--line-soft);
  background: #07080a;
}

.function-help-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(8, 9, 12, .03), rgba(8, 9, 12, .25));
}

.function-help-media video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  opacity: .82;
}

.function-help-body {
  padding: 13px 15px 15px;
}

.function-help-title {
  display: block;
  margin-bottom: 5px;
  color: var(--text);
  font-size: 15px;
  line-height: 1.25;
  font-weight: 650;
}

.function-help-title:empty {
  display: none;
}

.function-help-description {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.42;
}

html[data-theme="light"] .function-help-popover {
  box-shadow: 0 18px 42px rgba(28, 34, 46, .22), inset 0 1px 0 rgba(255, 255, 255, .38);
}

@media (prefers-reduced-motion: reduce) {
  .function-help-popover { transition: none; }
}

/* Complete user palette. Keep structural and semantic status colors intact,
   but route every regular menu surface/control through the configured theme. */
body { background:var(--background); }
.app-shell { background:transparent; }
.app-shell :where(h1,h2,h3,h4,strong,output) { color:var(--text); }
.app-shell :where(p,small,em) { color:var(--muted); }
.app-shell::before { background:radial-gradient(circle at 16% 8%,color-mix(in srgb,var(--text) 5.5%,transparent),transparent 25%),radial-gradient(circle at 92% 72%,color-mix(in srgb,var(--tertiary) 4%,transparent),transparent 30%); }
.sidebar { background:color-mix(in srgb,var(--sidebar) 94%,transparent);border-color:var(--line); }
.sidebar::before { background:linear-gradient(105deg,color-mix(in srgb,var(--text) 3.5%,transparent),transparent 24%,transparent 76%,color-mix(in srgb,var(--accent) 2.5%,transparent)); }
.sidebar::after { background:linear-gradient(180deg,color-mix(in srgb,var(--control-hover) 88%,transparent),color-mix(in srgb,var(--control) 91%,transparent));box-shadow:inset 0 1px color-mix(in srgb,var(--text) 5%,transparent),0 10px 28px color-mix(in srgb,var(--background) 18%,transparent); }
.workspace { background:radial-gradient(circle at 50% -160px,color-mix(in srgb,var(--text) 3.5%,transparent),transparent 44%),color-mix(in srgb,var(--background) 90%,transparent); }
/* A selected two-color background is already painted by .app-background-base.
   Keep the workspace's subtle lighting, without masking that gradient with a
   second nearly opaque solid (or the older light-mode decorative gradient). */
html.has-background-gradient:not(.has-background-media) .workspace { background:radial-gradient(circle at 50% -160px,color-mix(in srgb,var(--text) 3.5%,transparent),transparent 44%); }
.window-titlebar { overflow:visible;color:var(--text);background:var(--ui-window-titlebar-bg); }
html.has-background-media .sidebar { background:color-mix(in srgb,var(--sidebar) 84%,transparent);backdrop-filter:blur(18px) saturate(.86); }
html.has-background-media .workspace { background:color-mix(in srgb,var(--background) 70%,transparent); }
html.has-background-media .window-titlebar { background:color-mix(in srgb,var(--ui-window-titlebar-bg) 83%,transparent);backdrop-filter:blur(18px) saturate(.86); }
html.has-background-media :is(.card,.feature-card,.appearance-panel,.bind-manager-panel) { backdrop-filter:blur(18px) saturate(.88); }
.brand svg { fill:var(--text);filter:drop-shadow(0 7px 14px color-mix(in srgb,var(--text) 10%,transparent)); }
.brand,.topbar h1,.card strong,.feature-card strong,.master-row strong,.select-row strong,.range-row strong { color:var(--text); }
:is(.card,.feature-card) { border-color:var(--line);color:var(--text); }
.card { background:radial-gradient(circle at 14% -10%,color-mix(in srgb,var(--text) 6%,transparent),transparent 40%),color-mix(in srgb,var(--card) 94%,transparent); }
.nav-tabs::before { border-color:var(--line);background:linear-gradient(100deg,color-mix(in srgb,var(--accent) 11%,transparent),color-mix(in srgb,var(--text) 3.5%,transparent) 68%,color-mix(in srgb,var(--accent) 6%,transparent)); }
.nav-tabs button { color:var(--muted);border-color:var(--line-soft); }
.nav-tabs button strong,.account-copy strong { color:color-mix(in srgb,var(--text) 78%,var(--muted)); }
.nav-tabs button small,.account-copy small { color:var(--muted); }
.nav-tabs button .nav-tab-icon { stroke:var(--muted); }
.nav-tabs button:hover { color:var(--text);background:color-mix(in srgb,var(--accent) 4%,transparent); }
.nav-tabs button:hover :is(strong,small),.nav-tabs button:hover .nav-tab-icon { color:var(--text);stroke:var(--text); }
.nav-tabs button.is-active::after { background:var(--accent); }
