.sidebar-bottom { background:linear-gradient(180deg,color-mix(in srgb,var(--background) 34%,transparent),color-mix(in srgb,var(--background) 78%,transparent)); }
.sidebar-account:hover { background:color-mix(in srgb,var(--accent) 4%,transparent); }
.account-avatar { color:var(--text);border-color:var(--line-bright);background:radial-gradient(circle at 34% 28%,color-mix(in srgb,var(--text) 9%,transparent),transparent 38%),var(--control); }
.menu-search { border-color:var(--line);color:var(--muted);background:color-mix(in srgb,var(--control) 84%,transparent);box-shadow:inset 0 1px color-mix(in srgb,var(--text) 3%,transparent); }
.menu-search:focus-within { border-color:color-mix(in srgb,var(--accent) 34%,var(--line));background:var(--control);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 6%,transparent),inset 0 1px color-mix(in srgb,var(--text) 4%,transparent); }
.menu-search input { color:var(--text); }
