body :is(.settings-button,.bind-actions button) { border-color:color-mix(in srgb,var(--accent) 72%,var(--line));color:var(--on-accent);background:var(--accent); }
body :is(.settings-button,.bind-actions button):hover { box-shadow:0 10px 23px color-mix(in srgb,var(--accent) 19%,rgba(0,0,0,.25)); }
body .quiet-settings-button { color:var(--text);border-color:var(--line-bright);background:linear-gradient(180deg,color-mix(in srgb,var(--control) 92%,var(--text) 8%),var(--control)); }
.toggle-track { border-color:var(--line-bright);background:linear-gradient(180deg,var(--control),color-mix(in srgb,var(--control) 88%,var(--background))); }
.toggle:hover .toggle-track,.toggle.is-magnetized .toggle-track { border-color:color-mix(in srgb,var(--accent) 32%,var(--line));background:var(--control-hover); }
.toggle input:checked + .toggle-track { border-color:color-mix(in srgb,var(--enabled) 62%,var(--line));background:color-mix(in srgb,var(--enabled) 58%,var(--control));box-shadow:inset 0 1px 3px color-mix(in srgb,var(--background) 30%,transparent),0 0 15px color-mix(in srgb,var(--enabled) 14%,transparent); }
.toggle input:checked + .toggle-track .toggle-thumb { border-color:color-mix(in srgb,var(--on-enabled) 18%,var(--enabled));background:var(--on-enabled);box-shadow:0 3px 9px color-mix(in srgb,var(--background) 38%,transparent); }
.range-row { border-color:var(--line-bright);background:linear-gradient(180deg,var(--range-surface-top),var(--range-surface-bottom)); }
.range-row.napi-motion.is-napi-hot { border-color:color-mix(in srgb,var(--accent) 28%,var(--line));background:linear-gradient(180deg,var(--control-hover),var(--control)); }
