.app-shell .segments::before { background:var(--segment-active);border-color:var(--accent); }
.app-shell .segments button.is-active,.app-shell .segments button.is-active:hover { color:var(--on-accent); }
.appearance-tabs::before { background:var(--accent); }
.appearance-tabs button.is-active { color:var(--on-accent);mix-blend-mode:normal; }

:is(.choice-dropdown-trigger,.custom-select-button,.bind-actions .custom-select-button,select) { border-color:var(--line-bright)!important;color:var(--text)!important; }
:is(.choice-dropdown-trigger,.custom-select-button,.bind-actions .custom-select-button,select):hover { border-color:color-mix(in srgb,var(--accent) 32%,var(--line))!important; }
