.appearance-panel { width:min(720px,calc(100vw - 48px));max-height:min(720px,calc(100vh - 48px));background:radial-gradient(circle at 16% -18%,color-mix(in srgb,var(--text) 6.5%,transparent),transparent 38%),color-mix(in srgb,var(--background) 96%,transparent); }
