/* Script Studio and declarative script pages. */
.scripts-page { padding:18px 20px 22px;overflow:hidden; }
.scripts-toolbar>div:first-child { display:flex;flex-direction:column;gap:4px; }
.scripts-toolbar strong { font-size:18px;font-weight:650; }
