.script-unsaved-indicator { display:inline-flex;align-items:center;gap:7px;height:26px;padding:0 10px;border:1px solid color-mix(in srgb,#e4b657 36%,var(--line));border-radius:999px;color:color-mix(in srgb,#e9bb62 78%,var(--text));background:color-mix(in srgb,#d79a35 9%,var(--control));font-size:10px;font-weight:700;white-space:nowrap;box-shadow:inset 0 1px rgba(255,255,255,.025); }
