.scripts-layout>.card { min-width:0;height:100%;padding:0;overflow:hidden;border-radius:14px; }
.script-library { display:flex;flex-direction:column; }
.script-library>header { display:flex;align-items:center;justify-content:space-between;min-height:58px;padding:12px 13px;border-bottom:1px solid var(--line-soft); }
