/* Every scrollable menu surface uses the same quiet, rounded scrollbar.
   Chromium gives the standardized `scrollbar-width: thin` precedence over
   the WebKit pseudo-elements and brings the native arrow buttons back. Keep
   that property at `auto` in WebView2 so the custom arrowless style wins. */
* {
  scrollbar-width: auto !important;
  scrollbar-color: auto !important;
}
*::-webkit-scrollbar {
  width: 9px !important;
  height: 9px !important;
}
*::-webkit-scrollbar-track,
*::-webkit-scrollbar-track-piece,
*::-webkit-scrollbar-corner {
  background: transparent !important;
}
*::-webkit-scrollbar-button,
*::-webkit-scrollbar-button:single-button,
*::-webkit-scrollbar-button:double-button,
*::-webkit-scrollbar-button:vertical:decrement,
*::-webkit-scrollbar-button:vertical:increment,
*::-webkit-scrollbar-button:horizontal:decrement,
*::-webkit-scrollbar-button:horizontal:increment,
*::-webkit-scrollbar-button:start,
*::-webkit-scrollbar-button:end {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  -webkit-appearance: none !important;
}
*::-webkit-scrollbar-thumb {
  min-width: 42px !important;
  min-height: 42px !important;
  border: 3px solid transparent !important;
  border-radius: 999px !important;
  background: color-mix(in srgb,var(--muted) 42%,transparent) !important;
  background-clip: content-box !important;
}
*::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb,var(--text) 58%,transparent) !important;
  background-clip: content-box !important;
}

/* Data Studio follows the same neutral glass language as the main menu. */
html.data-studio-active .app-shell {
  border-color: color-mix(in srgb,var(--menu-accent) 30%,var(--line));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--menu-accent) 6%,transparent), inset 0 1px color-mix(in srgb,var(--text) 4%,transparent);
}

.data-studio-modal {
