  height: 6px;
  flex: 0 0 6px;
  border-radius: 50%;
  background: color-mix(in srgb,var(--muted) 70%,transparent);
}

.data-studio-workspace .dataset-capture-state.is-armed,
.data-studio-workspace .dataset-capture-state.is-active {
  border-color: color-mix(in srgb,var(--enabled) 34%,var(--line));
  color: color-mix(in srgb,var(--enabled) 76%,var(--text));
  background: color-mix(in srgb,var(--enabled) 7%,var(--control));
}

.data-studio-workspace .dataset-capture-state.is-armed::before,
.data-studio-workspace .dataset-capture-state.is-active::before {
  background: var(--enabled);
  box-shadow: 0 0 10px color-mix(in srgb,var(--enabled) 35%,transparent);
}

.data-studio-workspace .studio-tabs {
  display: flex;
  min-height: 58px;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb,var(--background-alt) 48%,var(--background));
}

.data-studio-workspace .studio-tabs button {
  position: relative;
  display: flex;
  width: min(250px,28vw);
  min-width: 164px;
  min-height: 41px;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 6px 13px;
  border: 1px solid transparent;
  border-radius: 11px;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  transition: color 150ms ease,border-color 150ms ease,background 150ms ease,box-shadow 150ms ease;
}

.data-studio-workspace .studio-tabs button::after { display: none; }

.data-studio-workspace .studio-tabs button > .lucide-icon {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.data-studio-workspace .studio-tabs button > span {
  display: grid;
  min-width: 0;
  gap: 2px;
  text-align: left;
}

.data-studio-workspace .studio-tabs button b {
  color: inherit;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .07em;
}

.data-studio-workspace .studio-tabs button small {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.data-studio-workspace .studio-tabs button:hover {
  border-color: var(--line);
  color: var(--text);
  background: color-mix(in srgb,var(--control-hover) 60%,transparent);
}

.data-studio-workspace .studio-tabs button.is-active {
  border-color: color-mix(in srgb,var(--accent) 20%,var(--line));
  color: var(--accent);
  background: linear-gradient(145deg,color-mix(in srgb,var(--accent) 8%,var(--control)),var(--control));
  box-shadow: inset 0 1px color-mix(in srgb,var(--text) 4%,transparent),0 8px 20px rgba(0,0,0,.16);
}

.data-studio-workspace .studio-tabs button.is-active small {
  color: color-mix(in srgb,var(--text) 58%,var(--muted));
}

.data-studio-workspace .data-studio-body {
  grid-template-columns: 224px minmax(0,1fr);
  background: color-mix(in srgb,var(--background) 97%,transparent);
}

.data-studio-workspace .studio-bind-panel {
  gap: 14px;
  padding: 18px 15px;
  border-right: 1px solid var(--line);
  background: color-mix(in srgb,var(--sidebar) 88%,var(--background));
}

.data-studio-workspace .studio-section-title {
  gap: 5px;
  padding: 0 2px 2px;
}

.data-studio-workspace .studio-section-title strong { font-size: 13px; }
.data-studio-workspace .studio-section-title small { font-size: 9px;line-height:1.4; }

.data-studio-workspace .studio-help {
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb,var(--control) 62%,transparent);
}

.data-studio-workspace .studio-help > i {
  width: 7px;
  height: 7px;
  flex-basis: 7px;
  background: var(--enabled);
  box-shadow: 0 0 10px color-mix(in srgb,var(--enabled) 30%,transparent);
}

.data-studio-workspace .studio-help strong { font-size: 10px; }
.data-studio-workspace .studio-help small { font-size: 9px;line-height:1.5; }

.data-studio-workspace .studio-pane {
  padding: 18px 20px 24px;
  background: radial-gradient(circle at 88% -10%,color-mix(in srgb,var(--text) 3.5%,transparent),transparent 31%);
  scrollbar-gutter: stable;
}

.data-studio-workspace .studio-pane > .card,
.data-studio-workspace .weapon-studio-grid > .card {
  border-color: var(--line);
  border-radius: 15px;
  background: radial-gradient(circle at 12% -16%,color-mix(in srgb,var(--text) 5%,transparent),transparent 38%), color-mix(in srgb,var(--card) 96%,transparent);
  box-shadow: var(--panel-shadow);
}

