  display: grid;
  grid-template-columns: minmax(360px,1fr) minmax(230px,290px);
  align-content: start;
  align-items: start;
  gap: 16px;
}

.data-studio-workspace .studio-pane[data-studio-pane="team"] .studio-dataset-card { margin: 0; }

.data-studio-workspace .studio-tip {
  display: grid;
  grid-template-columns: 34px minmax(0,1fr);
  align-items: start;
  gap: 10px 11px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: color-mix(in srgb,var(--card) 82%,transparent);
  box-shadow: inset 0 1px color-mix(in srgb,var(--text) 3%,transparent);
}

.data-studio-workspace .studio-tip > span {
  width: 30px;
  height: 30px;
  border-color: var(--line-bright);
  border-radius: 9px;
  color: var(--text);
  background: var(--control);
  font: 700 9px "Ubuntu",sans-serif;
}

.data-studio-workspace .studio-tip p { align-self:center;gap:3px; }
.data-studio-workspace .studio-tip p strong { font-size: 10px; }
.data-studio-workspace .studio-tip p small { font-size: 9px;line-height:1.45; }

.data-studio-workspace .feature-card { padding: 17px 18px; }
.data-studio-workspace .feature-card-head { min-height: 46px; }
.data-studio-workspace .feature-card-title strong { font-size: 18px; }
.data-studio-workspace .feature-card-title small { margin-top:5px;font-size:11px; }
.data-studio-workspace .feature-card-body { margin-top:14px;padding-top:14px; }
.data-studio-workspace .feature-card-footer { margin-top:15px;padding-top:14px; }

.data-studio-workspace .region-summary {
  min-height: 54px;
  margin-top: 11px;
  padding: 10px 13px;
  border-color: var(--line-bright);
  border-radius: 11px;
  color: var(--text);
  background: linear-gradient(145deg,color-mix(in srgb,var(--control) 92%,var(--text) 3%),var(--control));
  box-shadow: var(--control-inset);
}

.data-studio-workspace .region-summary:hover {
  border-color: color-mix(in srgb,var(--accent) 32%,var(--line));
  background: var(--control-hover);
  transform: none;
}

.data-studio-workspace .region-summary strong { font-size: 11px; }
.data-studio-workspace .region-summary small { margin-top:4px;font-size:9px; }
.data-studio-workspace .region-summary em { color:var(--text);font:700 8px "Ubuntu",sans-serif;letter-spacing:.06em; }

.data-studio-workspace .dataset-capture-button {
  min-height: 58px;
  margin-top: 13px;
  padding: 10px 14px;
  border-color: color-mix(in srgb,var(--accent) 64%,var(--line));
  border-radius: 12px;
  color: var(--on-accent);
  background: var(--accent);
  box-shadow: 0 10px 24px color-mix(in srgb,var(--accent) 13%,rgba(0,0,0,.22));
}

.data-studio-workspace .dataset-capture-button:hover {
  border-color: var(--accent);
  color: var(--on-accent);
  background: color-mix(in srgb,var(--accent) 88%,var(--text));
}

.data-studio-workspace .dataset-capture-button > .lucide-icon { stroke:currentColor; }
.data-studio-workspace .dataset-capture-button b { color:inherit;font-size:11px; }
.data-studio-workspace .dataset-capture-button small { color:color-mix(in srgb,var(--on-accent) 62%,transparent);font-size:9px; }

.data-studio-workspace .weapon-studio-grid {
  grid-template-columns: minmax(390px,1.25fr) minmax(250px,.75fr);
  gap: 16px;
}

.data-studio-workspace .weapon-studio-grid > .card { margin-bottom:16px; }
.data-studio-workspace .weapon-studio-grid .recognition-preview-card { overflow:hidden; }
.data-studio-workspace .weapon-preview-frame {
  overflow: hidden;
  border-color: var(--line-bright);
  border-radius: 12px;
  background: radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--text) 4%,transparent),transparent 68%),var(--background);
}

.data-studio-workspace .training-progress span {
  background: var(--accent);
  box-shadow: 0 0 10px color-mix(in srgb,var(--accent) 20%,transparent);
