@media (max-width:900px) {
  .studio-header-separator { display:none; }
  .data-studio-workspace .studio-heading { min-width:150px; }
  .data-studio-workspace .dataset-capture-state { display:none; }
  .data-studio-workspace .studio-project-cluster { width:min(270px,38vw);min-width:190px; }
  .data-studio-workspace .data-studio-body { grid-template-columns:190px minmax(0,1fr); }
  .data-studio-workspace .studio-pane[data-studio-pane="team"]:not([hidden]) { grid-template-columns:1fr; }
  .data-studio-workspace .studio-tip { grid-template-columns:34px minmax(0,1fr) 34px minmax(0,1fr); }
  .data-studio-workspace .weapon-studio-grid { grid-template-columns:1fr; }
}

