/* The first-run workspace owns the full NAIM client area.  The native host
   keeps the outer rounded-window clip; only the cards inside the workspace
   retain their own radii and shadows. */
.first-login-onboarding{
  padding:0;
  place-items:stretch;
}
.first-login-onboarding-panel{
  box-sizing:border-box;
  width:100%;
  min-width:0;
  max-width:none;
  height:100%;
  min-height:0;
  max-height:none;
  border:0;
  border-radius:0;
  box-shadow:none;
}
.first-login-onboarding-panel>header.window-titlebar{
  min-width:0;
  user-select:none;
}

/* Preview annotations live above the GPU canvas, so changing offsets never
   uploads or repaints the video frame. */
.setup-scan-region{
  position:absolute;
  left:var(--setup-scan-left,0%);
  top:var(--setup-scan-top,0%);
  width:var(--setup-scan-width,100%);
  height:var(--setup-scan-height,100%);
  box-sizing:border-box;
  border:1px dashed rgba(248,249,250,.88);
  border-radius:2px;
  filter:drop-shadow(0 1px 2px rgba(0,0,0,.72));
}

/* WebKit centres its native range track on fractional device pixels.  Draw
   the shared range fill on the clipped component surface instead, using the
   same --fill value maintained by updateRange. */
