/* Contextual lessons use the production toast stack and toast surface so they
   stay visually identical to ordinary bottom-right notifications. */
.context-guide-toast {
  position:relative;
  width:100%;
  box-sizing:border-box;
  gap:8px;
  padding:9px 10px;
  overflow:hidden;
  pointer-events:auto;
  opacity:0;
  visibility:hidden;
  transform:translateY(8px) scale(.98);
  transform-origin:right bottom;
  animation:none;
  transition:opacity 170ms ease,transform 220ms var(--motion),visibility 0s linear 220ms;
}
.context-guide-toast[hidden] { display:none; }
.context-guide-toast.is-open { opacity:1;visibility:visible;transform:none;transition-delay:0s; }
.context-guide-toast-copy { flex:1 1 auto;gap:2px;padding-right:0;align-self:center; }
.context-guide-toast-copy strong { line-height:1.22; }
.context-guide-toast-copy small { order:2;color:var(--muted); }
.context-guide-toast-open { flex:0 0 auto;align-self:center;margin:0 0 0 auto;white-space:nowrap; }
/* Lesson actions are ordinary theme buttons, not enabled/success indicators. */
:is(.hotkey-root-help>button, .context-guide-toast-open) {
  border-color:var(--line-bright);
  color:var(--text);
  background:var(--control);
  box-shadow:var(--control-inset);
}
:is(.hotkey-root-help>button, .context-guide-toast-open):not(:disabled):is(:hover, :focus-visible) {
  border-color:color-mix(in srgb,var(--accent) 52%,var(--line-bright));
  color:var(--text);
  background:color-mix(in srgb,var(--accent) 10%,var(--control-hover));
}
:is(.hotkey-root-help>button, .context-guide-toast-open):focus-visible {
  outline:2px solid color-mix(in srgb,var(--accent) 70%,var(--text));
  outline-offset:2px;
}
:is(.hotkey-root-help>button, .context-guide-toast-open):disabled {
  opacity:.42;
  cursor:default;
  box-shadow:none;
}
.notification>.context-guide-toast-timer { position:absolute;display:block;left:0;right:0;bottom:0;width:auto;height:2px;overflow:hidden;border-radius:0;background:color-mix(in srgb,var(--text) 7%,transparent); }
.context-guide-toast-timer::after { content:"";display:block;width:100%;height:100%;border-radius:inherit;background:color-mix(in srgb,var(--accent) 76%,var(--text));transform-origin:left center; }
.context-guide-toast.is-open:not(.is-paused) .context-guide-toast-timer::after { animation:context-guide-toast-countdown 10s linear forwards; }
.context-guide-toast.is-paused .context-guide-toast-timer::after { transform:scaleX(1); }
@keyframes context-guide-toast-countdown { from{transform:scaleX(1)} to{transform:scaleX(0)} }

/* Startup hotkey guide. Its miniature controls and popovers deliberately
   reuse the production menu classes so the lesson always matches the UI. */
.bind-tutorial {
  position: fixed;
  z-index: 900;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 22px;
  color: var(--text);
  background: color-mix(in srgb,var(--bg) 68%,transparent);
  -webkit-backdrop-filter: blur(16px) brightness(.62) saturate(.58);
  backdrop-filter: blur(16px) brightness(.62) saturate(.58);
  opacity: 0;
  visibility: hidden;
  transition: opacity 190ms ease,visibility 0s linear 190ms;
}
.bind-tutorial[hidden] { display:none; }
.bind-tutorial.is-open { opacity:1;visibility:visible;transition-delay:0s; }
.bind-tutorial-panel {
  display: grid;
  width: min(760px,calc(100vw - 44px));
  max-height: calc(100vh - 44px);
  overflow: hidden;
  border: 1px solid var(--line-bright);
  border-radius: 19px;
  background: radial-gradient(circle at 14% -8%,color-mix(in srgb,var(--text) 7%,transparent),transparent 38%),var(--bg);
  box-shadow: 0 36px 105px rgba(0,0,0,.7),inset 0 1px color-mix(in srgb,var(--text) 6%,transparent);
  opacity: 0;
  transform: translateY(12px) scale(.982);
  transition: opacity 190ms ease,transform 230ms cubic-bezier(.2,.8,.2,1);
}
.bind-tutorial.is-open .bind-tutorial-panel { opacity:1;transform:none; }
.bind-tutorial-header {
  display: flex;
  min-height: 56px;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 0 17px 0 20px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb,var(--card) 72%,transparent);
}
.bind-tutorial-header>span { display:grid;gap:4px; }
.bind-tutorial-header small { color:var(--muted);font-size:11px;line-height:1;letter-spacing:.12em; }
.bind-tutorial-header strong { font-size:20px;line-height:1.08;font-weight:680; }
.bind-tutorial-stage {
  position: relative;
  height: 310px;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background:
    radial-gradient(circle at 74% 32%,rgba(85,227,164,.07),transparent 30%),
    linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px),
    color-mix(in srgb,var(--background) 82%,#050608);
  background-size: auto,28px 28px,28px 28px,auto;
  isolation: isolate;
  pointer-events: none;
}
.bind-tutorial-stage::before {
  content:"";
  position:absolute;
  z-index:0;
  inset:0;
  background:linear-gradient(90deg,transparent 0 68%,rgba(0,0,0,.12)),linear-gradient(180deg,transparent 68%,rgba(0,0,0,.2));
}
.bind-tutorial-demo-card {
  position: absolute;
  z-index: 1;
  left: 28px;
  top: 28px;
  width: 415px;
  overflow: hidden;
  border: 1px solid var(--line-bright);
  border-radius: 15px;
  background: color-mix(in srgb,var(--card) 94%,transparent);
  box-shadow: 0 22px 52px rgba(0,0,0,.34),inset 0 1px color-mix(in srgb,var(--text) 5%,transparent);
}
.bind-tutorial-demo-card .feature-card-head { min-height:62px;padding:0 17px; }
.bind-tutorial-demo-card .feature-card-title { display:grid;gap:4px; }
.bind-tutorial-demo-card .feature-card-title strong { font-size:17px!important; }
.bind-tutorial-demo-card .feature-card-title small { color:var(--muted);font-size:10px; }
.bind-tutorial-demo-card .feature-switch { display:flex;align-items:center;gap:10px; }
.bind-tutorial-demo-card .feature-switch>span { color:var(--enabled);font-size:10px;font-weight:650; }
.bind-tutorial-demo-body { display:grid;gap:3px;padding:12px 17px 15px;border-top:1px solid var(--line-soft); }
.bind-tutorial-demo-body .range-row { width:100%;height:67px;min-height:67px; }
.bind-tutorial-demo-body .master-row { min-height:66px;padding:0 3px;border-top:1px solid var(--line-soft); }
.bind-tutorial-demo-body .master-row>span { display:grid;gap:4px; }
.bind-tutorial-demo-body .master-row small { color:var(--muted);font-size:10px; }
.bind-tutorial-target { position:relative; }
.bind-tutorial-target::after {
  content:"";
  position:absolute;
  right:-8px;
  top:50%;
  width:58px;
  height:44px;
