/* Refined startup lessons: production controls on the left, an explicit
   cause/effect timeline on the right. */
.bind-tutorial {
  --guide-warning:#f1c56a;
  --guide-danger:#ef747a;
  --guide-predict:#aa8cff;
  --guide-result:#76b8ff;
}
.bind-tutorial-panel { width:min(1040px,calc(100vw - 44px)); }
.bind-tutorial-stage { height:386px; }
.aim-guide-scene {
  --guide-cycle:var(--tutorial-slide-duration,8s);
  grid-template-columns:410px minmax(0,1fr);
  gap:14px;
  padding:14px;
}
.aim-guide-control-column { position:relative;z-index:3;display:flex;min-width:0;align-self:center;flex-direction:column;gap:10px; }
