.aim-guide-phase-strip>span { display:flex;min-width:0;height:38px;align-items:center;gap:8px;padding:0 10px;border:1px solid var(--line);border-radius:9px;color:var(--muted);background:color-mix(in srgb,var(--control) 82%,transparent);opacity:.48;transition:none; }
