.setup-config-recovery-status{color:var(--danger)!important}
.setup-offset-range{position:relative;display:block!important;margin:0!important}

/* Onboarding and the RCS editor follow the current theme. The RCS feature
   card keeps the shared enabled color so its active switches stay green. */
.first-login-onboarding,
.rcs-editor-modal {
  --enabled: var(--accent);
  --enabled-soft: color-mix(in srgb,var(--accent) 13%,transparent);
  --on-enabled: var(--on-accent);
}

/* Make the welcome choices occupy the available stage instead of leaving a
   dead strip under two short cards. */
.setup-stage[data-setup-stage="0"] .setup-welcome-options {
  height: 100%;
  min-height: 0;
  flex: 1 1 auto;
}
.setup-welcome-options>.setup-import-drop {
  display: flex;
  align-items: stretch;
  justify-content: stretch;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border-style: solid!important;
}
.setup-import-target {
  position: relative;
  z-index: 1;
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 16px;
  padding: 28px 22px;
  border: 2px dashed color-mix(in srgb,var(--accent) 32%,var(--line-bright));
  border-radius: 14px;
  background: color-mix(in srgb,var(--accent) 3%,var(--background));
  text-align: center;
  transition: border-color 160ms ease,background 160ms ease,transform 170ms var(--motion);
}
.setup-import-glyph {
  position: relative;
  display: grid;
  width: 70px;
  height: 70px;
  place-items: center;
  border: 1px solid color-mix(in srgb,var(--accent) 34%,var(--line));
  border-radius: 21px;
  color: var(--accent);
  background: color-mix(in srgb,var(--accent) 9%,var(--control));
  box-shadow: inset 0 1px color-mix(in srgb,var(--text) 6%,transparent),0 12px 32px rgba(0,0,0,.18);
}
.setup-import-glyph::after {
  content: "↑";
  position: absolute;
  right: -7px;
  bottom: -7px;
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 2px solid var(--background);
  border-radius: 50%;
  color: var(--on-accent);
  background: var(--accent);
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}
.setup-import-glyph svg {
  width: 31px;
  height: 31px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.55;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.setup-import-target>span:last-child {
  display: grid;
  gap: 7px;
}
.setup-import-target strong { font-size: 16px; }
.setup-import-target small { max-width: 260px;font-size: 10px;line-height: 1.5; }
.setup-import-drop>em {
  position: static;
  z-index: 1;
  display: block;
  min-height: 14px;
  color: var(--muted);
  font-size: 8px;
  font-style: normal;
  text-align: center;
}
.setup-import-drop::after { z-index: 2; }
.setup-import-drop:hover .setup-import-target,
.setup-import-drop.is-dragging .setup-import-target {
  border-color: color-mix(in srgb,var(--accent) 68%,var(--line-bright));
  background: color-mix(in srgb,var(--accent) 9%,var(--background));
  transform: translateY(-2px);
}

.setup-welcome-options>.setup-new-card {
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  flex-direction: column;
  gap: 0;
  padding: 32px;
}
.setup-new-card .first-login-option-icon {
  width: 60px;
  height: 60px;
  flex: 0 0 60px;
  border-radius: 17px;
  border-color: color-mix(in srgb,var(--accent) 28%,var(--line));
  color: var(--accent);
  background: color-mix(in srgb,var(--accent) 7%,var(--background));
}
.setup-new-card .first-login-option-icon svg { width: 27px;height: 27px; }
.setup-welcome-options>.setup-new-card>span:nth-child(2) {
  margin-top: 24px;
  gap: 9px;
}
.setup-new-card strong { font-size: 17px; }
.setup-new-card small { max-width: 310px;font-size: 10px;line-height: 1.55; }
.setup-new-card .first-login-option-arrow {
  box-sizing: border-box;
  width: 52px;
  height: 52px;
  margin: auto 0 0 auto;
  padding: 11px;
  border: 1px solid color-mix(in srgb,var(--accent) 34%,var(--line));
  border-radius: 16px;
  color: var(--accent);
  background: color-mix(in srgb,var(--accent) 8%,var(--control));
  transition: transform 170ms var(--motion),background 160ms ease;
}
.setup-new-card:hover .first-login-option-arrow {
  background: color-mix(in srgb,var(--accent) 14%,var(--control));
  transform: translateX(3px);
}

.rcs-editor-workspace {
  border-color: color-mix(in srgb,var(--accent) 22%,var(--line));
  background: linear-gradient(145deg,color-mix(in srgb,var(--accent) 3%,var(--card)),var(--bg));
}
.rcs-editor-workspace>header {
  border-bottom-color: var(--line-soft);
  background: linear-gradient(90deg,color-mix(in srgb,var(--accent) 6%,var(--control)),transparent 45%);
}
.rcs-editor-workspace .workspace-back {
  border-color: color-mix(in srgb,var(--accent) 16%,var(--line));
  color: var(--text);
  background: color-mix(in srgb,var(--accent) 4%,var(--control));
}
.rcs-editor-workspace .workspace-back:hover {
  border-color: color-mix(in srgb,var(--accent) 42%,var(--line-bright));
}
.rcs-editor-workspace .workspace-count {
  color: var(--accent);
  background: color-mix(in srgb,var(--accent) 9%,transparent);
}

/* Keep onboarding and RCS on the same component language as the main menu. */
.first-login-onboarding-panel,
.rcs-editor-workspace {
  font-family: "Ubuntu", "Segoe UI", sans-serif;
}
.first-login-onboarding-panel {
  position:relative;
  border-color: var(--line-bright);
  background: var(--card-surface);
  box-shadow: 0 30px 84px rgba(0,0,0,.58), inset 0 1px color-mix(in srgb,var(--text) 6%,transparent);
}
.setup-card,
.setup-benchmark-intro,
.rcs-editor-controls>section {
  border-color: var(--line);
  background: var(--card-surface);
  box-shadow: var(--panel-shadow);
}
.setup-source-tabs,
.rcs-mode-switch {
  border-color: var(--line);
  background: color-mix(in srgb,var(--control) 82%,var(--background));
  box-shadow: var(--control-inset);
}
.setup-source-tabs button,
.rcs-mode-switch button {
  min-height: 34px;
  color: var(--muted);
  font: 700 11px "Ubuntu",sans-serif;
}
.setup-source-tabs button:hover,
.rcs-mode-switch button:hover {
  color: var(--text);
  background: var(--control-hover);
}
.setup-source-tabs button.is-active,
.rcs-mode-switch button.is-active {
  color: var(--on-accent);
  background: var(--accent);
  box-shadow: inset 0 1px color-mix(in srgb,var(--text) 34%,transparent),0 6px 15px rgba(0,0,0,.2);
}
.setup-controls-card label>span,
.setup-card-heading strong { font-size:11px; }
