/* Independent moving glass for mutually exclusive choices.  Every registered
   group owns one lens; the sidebar keeps its separate nav-tabs::before glass. */
[data-glass-selector] {
  --glass-selector-x: 0px;
  --glass-selector-y: 0px;
  --glass-selector-width: 0px;
  --glass-selector-height: 0px;
  --glass-selector-radius: 10px;
  position: relative;
  isolation: isolate;
}

[data-glass-selector] > .glass-selector-lens {
  position: absolute;
  z-index: 0;
  left: 0;
  top: 0;
  display: block;
  box-sizing: border-box;
  width: var(--glass-selector-width);
  height: var(--glass-selector-height);
  border: 1px solid color-mix(in srgb,var(--text) 12%,transparent);
  border-radius: var(--glass-selector-radius);
  opacity: 0;
  background:
    linear-gradient(105deg,
      color-mix(in srgb,var(--text) 10%,transparent),
      color-mix(in srgb,var(--accent) 5%,transparent) 62%,
      color-mix(in srgb,var(--text) 6%,transparent));
  -webkit-backdrop-filter: blur(11px) saturate(.72);
  backdrop-filter: blur(11px) saturate(.72);
  box-shadow:
    inset 0 1px color-mix(in srgb,var(--text) 7%,transparent),
    0 7px 18px rgba(0,0,0,.14);
  transform: translate3d(var(--glass-selector-x),var(--glass-selector-y),0);
  transition:
    transform 280ms cubic-bezier(.2,.78,.2,1),
    width 280ms cubic-bezier(.2,.78,.2,1),
    height 280ms cubic-bezier(.2,.78,.2,1),
    border-radius 220ms ease,
    opacity 160ms ease;
  pointer-events: none;
  will-change: transform,width,height;
}

[data-glass-selector].has-glass-target > .glass-selector-lens { opacity: 1; }
[data-glass-selector].glass-selector-no-motion > .glass-selector-lens { transition: none; }

[data-glass-selector] > button {
  position: relative;
  z-index: 1;
  transform: translateZ(0) scale(1);
  transform-origin: center;
  transition-property: color,border-color,opacity,transform;
  transition-duration: 170ms;
  transition-timing-function: ease;
}

[data-glass-selector] > button:hover,
[data-glass-selector] > button.is-active,
[data-glass-selector] > button.is-selected,
[data-glass-selector] > button.is-glass-target {
  color: var(--text);
  background: transparent!important;
  box-shadow: none!important;
}

[data-glass-selector] > button.is-glass-target:not(:disabled) {
  z-index: 2;
  color: var(--text)!important;
  transform: translateZ(0) scale(1.025);
}

[data-glass-selector].studio-tabs > button.is-active,
[data-glass-selector].studio-workflow-nav > button.is-active,
[data-glass-selector].status-hud-anchor-grid > button.is-active {
  border-color: transparent!important;
}

[data-glass-selector].status-hud-anchor-grid > .glass-selector-lens {
  box-shadow:
    inset 0 1px color-mix(in srgb,var(--text) 8%,transparent),
    0 0 12px color-mix(in srgb,var(--accent) 18%,transparent);
}

[data-glass-selector].appearance-tabs::before,
[data-glass-selector].segments::before { display: none; }

.hotkey-mode > [data-glass-selector] > i.glass-selector-lens {
  left: 0;
  top: 0;
}

@media (prefers-reduced-motion: reduce) {
  [data-glass-selector] > .glass-selector-lens,
  [data-glass-selector] > button { transition-duration: 1ms!important; }
}
