.setup-calibration-return { position:absolute;left:50%;top:50%;width:42%;height:1px;opacity:0;background:linear-gradient(90deg,transparent,var(--accent),transparent);transform:translate(-50%,-50%);transition:opacity 180ms ease; }
.setup-bind-animation[data-phase="return"] .setup-calibration-return { opacity:.75;animation:setupCalibrationReturn 900ms ease-in-out infinite; }
.setup-bind-animation[data-phase="reference"] .setup-cursor-dot { animation:setupCalibrationReference 900ms ease-in-out infinite; }
.setup-bind-animation[data-phase="rotate"] .setup-cursor-dot { animation:setupCalibrationRotate 1.1s ease-in-out infinite; }
