  font:700 9px "Ubuntu",sans-serif;
  letter-spacing:.1em;
}
.rcs-editor-controls label { grid-template-columns:minmax(0,1fr) 76px;min-height:46px;gap:10px; }
.rcs-editor-controls label strong { font-size:11px; }
.rcs-editor-controls label small,
.rcs-editor-controls p { font-size:9px;line-height:1.5; }
.rcs-editor-controls label input {
  width:76px;
  height:var(--ui-control-height);
  padding-right:32px;
  border-color:var(--line);
  border-radius:var(--ui-control-radius);
  background:var(--control);
  box-shadow:var(--control-inset);
  font:650 11px "Ubuntu",sans-serif;
}
.rcs-editor-controls label input:focus {
  border-color:color-mix(in srgb,var(--accent) 45%,var(--line-bright));
  box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 8%,transparent),var(--control-inset);
}
.rcs-editor-controls label em { right:7px;bottom:13px;font:700 8px "Ubuntu",sans-serif; }
.rcs-record-button { min-height:var(--ui-action-height);font-size:11px; }
.rcs-record-status { font-size:9px; }
.rcs-editor-help button { min-height:34px;font-size:11px; }
.rcs-graph-head strong,
.rcs-graph-panel>footer { font-size:9px; }
.rcs-graph-legend { font-size:9px; }
@media (max-height:760px) {
  .rcs-editor-modal { padding:14px; }
  .rcs-editor-controls { gap:8px;padding:10px; }
  .rcs-editor-controls>section { gap:7px;padding:10px; }
  .rcs-editor-controls label { min-height:40px;padding-top:6px; }
}
.rcs-editor-controls label.rcs-editor-range-row {
  display:block;
  width:100%;
  height:var(--ui-range-height);
  min-height:var(--ui-range-height);
  margin:0;
  padding:0;
  overflow:hidden;
  border:1px solid var(--line-bright);
  border-radius:var(--ui-pill-radius);
  background:linear-gradient(180deg,var(--range-surface-top),var(--range-surface-bottom));
  box-shadow:inset 0 1px rgba(255,255,255,.05),inset 0 -1px rgba(0,0,0,.26),0 5px 14px rgba(0,0,0,.10);
}
.rcs-editor-controls label.rcs-editor-range-row>span {
  position:absolute;
  z-index:2;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:0 12px;
}
.rcs-editor-controls label.rcs-editor-range-row strong,
.rcs-editor-controls label.rcs-editor-range-row output {
  font:600 11px "Ubuntu",sans-serif;
}
.rcs-editor-controls label.rcs-editor-range-row input[type="range"] {
  position:absolute;
  z-index:1;
  inset:0;
  width:100%;
  height:100%;
  margin:0;
  padding:0;
  border:0;
  border-radius:inherit;
  background:transparent;
  box-shadow:none;
  text-align:initial;
}
.rcs-editor-workspace {
  width:min(1400px,100%);
  height:min(800px,100%);
}
.rcs-editor-layout {
  grid-template-columns:276px minmax(360px,1fr) 248px;
  overflow:hidden;
}
.rcs-studio-library {
  grid-column:1;
  grid-row:1;
  display:grid;
  grid-template-rows:minmax(128px,.64fr) minmax(260px,1.36fr);
  gap:10px;
  min-width:0;
  min-height:0;
  padding:12px;
  overflow:hidden;
  border-right:1px solid var(--line-soft);
  background:linear-gradient(180deg,color-mix(in srgb,var(--control) 34%,transparent),transparent);
}
.rcs-studio-library>section {
  display:flex;
  flex-direction:column;
  gap:9px;
  min-height:0;
  padding:11px;
  overflow:hidden;
  border:1px solid var(--line);
  border-radius:var(--ui-control-radius);
  background:var(--card-surface);
  box-shadow:var(--panel-shadow);
}
.rcs-studio-library section>header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  min-width:0;
}
.rcs-studio-library section>header>span {
  display:grid;
  min-width:0;
  gap:3px;
}
.rcs-studio-library section>header small {
  color:var(--muted);
  font-size:8px;
  font-weight:700;
  letter-spacing:.1em;
}
.rcs-studio-library section>header strong {
  overflow:hidden;
  color:var(--text);
  font-size:11px;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.rcs-studio-weapons {
  display:grid;
  grid-template-columns:1fr 1fr;
  align-content:start;
  gap:6px;
  min-height:0;
  padding-right:3px;
  overflow-x:hidden;
  overflow-y:auto;
}
.rcs-studio-weapon-tab {
  display:flex;
  align-items:center;
  gap:7px;
  min-width:0;
  min-height:34px;
  padding:0 8px;
  overflow:hidden;
  border:1px solid var(--line-soft);
  border-radius:8px;
  color:var(--muted);
  background:color-mix(in srgb,var(--control) 64%,transparent);
  cursor:pointer;
  font:650 9px "Ubuntu",sans-serif;
  text-align:left;
  transition:border-color 120ms ease,color 120ms ease,background 120ms ease;
}
.rcs-studio-weapon-tab::before {
  content:"";
  flex:0 0 5px;
  width:5px;
  height:5px;
  border-radius:50%;
  background:color-mix(in srgb,var(--muted) 55%,transparent);
}
.rcs-studio-weapon-tab>span {
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.rcs-studio-weapon-tab:hover {
  color:var(--text);
  border-color:var(--line-bright);
  background:var(--control-hover);
}
.rcs-studio-weapon-tab.is-active {
  color:var(--text);
  border-color:color-mix(in srgb,var(--accent) 40%,var(--line));
  background:color-mix(in srgb,var(--accent) 9%,var(--control));
}
.rcs-studio-weapon-tab.is-active::before {
  background:var(--accent);
  box-shadow:0 0 8px color-mix(in srgb,var(--accent) 65%,transparent);
}
.rcs-studio-patterns-section>p {
  margin:0;
  color:var(--muted);
  font-size:8px;
  line-height:1.4;
}
body .rcs-studio-add-pattern {
  display:grid;
  flex:0 0 32px;
  width:32px;
  height:32px;
  min-height:32px;
  padding:0;
  place-items:center;
  justify-content:center;
}
.rcs-studio-add-pattern .lucide-icon {
  width:14px;
  height:14px;
  color:var(--on-accent);
  stroke:var(--on-accent);
}
.rcs-studio-pattern-list {
  display:grid;
  align-content:start;
  gap:7px;
  min-height:0;
  padding-right:3px;
  overflow-x:hidden;
  overflow-y:auto;
}
.rcs-studio-pattern-list.is-loading {
  place-items:center;
  align-content:center;
}
.rcs-studio-pattern-loading {
  color:var(--muted);
  font-size:9px;
  text-align:center;
}
.rcs-studio-pattern-card {
  display:grid;
  grid-template-columns:86px minmax(0,1fr);
  align-items:center;
  gap:9px;
  width:100%;
  min-width:0;
  min-height:76px;
  padding:7px;
  overflow:hidden;
  border:1px solid var(--line-soft);
  border-radius:9px;
  color:var(--muted);
  background:color-mix(in srgb,var(--control) 60%,transparent);
  cursor:pointer;
  text-align:left;
  transition:border-color 120ms ease,background 120ms ease,transform 110ms var(--motion);
}
.rcs-studio-pattern-card:hover {
  border-color:var(--line-bright);
  background:var(--control-hover);
}
.rcs-studio-pattern-card:active { transform:scale(.985); }
.rcs-studio-pattern-card.is-selected {
  border-color:color-mix(in srgb,var(--accent) 44%,var(--line));
  background:color-mix(in srgb,var(--accent) 8%,var(--control));
  box-shadow:inset 0 1px color-mix(in srgb,var(--text) 3%,transparent);
}
.rcs-studio-pattern-card canvas {
  width:86px;
  height:60px;
  border:1px solid var(--line-soft);
  border-radius:7px;
  background:color-mix(in srgb,var(--background) 82%,#020304);
}
.rcs-studio-pattern-card>span {
  display:grid;
  min-width:0;
  gap:5px;
}
.rcs-studio-pattern-card strong,
.rcs-studio-pattern-card small {
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.rcs-studio-pattern-card strong {
  color:var(--text);
  font-size:10px;
}
.rcs-studio-pattern-card small {
  color:var(--muted);
  font-size:8px;
}
.rcs-studio-pattern-card em {
  justify-self:start;
  padding:3px 6px;
  border-radius:99px;
  color:var(--muted);
  background:color-mix(in srgb,var(--text) 5%,transparent);
  font:normal 700 7px "Ubuntu",sans-serif;
  letter-spacing:.04em;
}
.rcs-studio-pattern-card.is-runtime-active em {
  color:var(--accent);
  background:color-mix(in srgb,var(--accent) 10%,transparent);
}
.rcs-studio-pattern-hint {
  min-height:12px;
  overflow:hidden;
  color:var(--muted);
  font-size:8px;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.rcs-studio-patterns-section .rcs-variant-actions {
  grid-template-columns:1fr 1fr;
}
.rcs-studio-patterns-section .rcs-variant-actions:has(button[hidden]:first-child) {
  display:none;
}
.rcs-editor-controls {
  grid-column:3;
}
.rcs-graph-panel {
  grid-column:2;
}
.rcs-record-target {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:9px;
  min-width:0;
  min-height:34px;
  padding:7px 9px;
  border:1px solid var(--line-soft);
  border-radius:var(--ui-control-radius);
  background:color-mix(in srgb,var(--control) 82%,transparent);
}
.rcs-record-target>small {
  flex:0 0 auto;
  color:var(--muted);
  font-size:8px;
  letter-spacing:.08em;
}
.rcs-record-target>strong {
  min-width:0;
  overflow:hidden;
  color:var(--text);
  font-size:9px;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.rcs-record-target.is-conditional {
  border-color:color-mix(in srgb,var(--accent) 34%,var(--line));
  background:color-mix(in srgb,var(--accent) 7%,var(--control));
}
@media (max-width:980px) {
  .rcs-editor-layout {
    grid-template-columns:220px minmax(340px,1fr) 220px;
    overflow-x:auto;
  }
  .rcs-studio-library { padding:9px; }
  .rcs-studio-library>section { padding:9px; }
  .rcs-studio-pattern-card { grid-template-columns:72px minmax(0,1fr); }
  .rcs-studio-pattern-card canvas { width:72px; }
}

/* Final component overrides: keep these after the shared menu-theme rules. */
