  width:100%;
  min-width:0;
  max-width:none;
  height:100%;
  min-height:0;
  max-height:none;
  padding:0;
  border:0;
  border-radius:0;
  background:var(--card-surface);
  box-shadow:none;
}
.first-login-onboarding-panel>header.window-titlebar{
  min-height:0;
  padding:18px 24px 15px;
  border-bottom:1px solid var(--line-soft);
  background:transparent;
