  backdrop-filter:none;
  box-shadow:none;
}
.first-login-onboarding-panel>header.window-titlebar::before{display:none}
.first-login-onboarding-panel>.setup-config-recovery-inline{
  margin:14px 24px 0;
}
.first-login-onboarding-panel>.setup-stage-stack{
