/* Benchmark welcome: useful visual structure without a second action button. */
.setup-benchmark-intro{
  position:relative;
  display:grid;
  width:min(780px,100%);
  max-width:none;
  gap:24px;
  margin:auto;
  padding:30px;
  overflow:hidden;
  border-radius:18px;
  background:
    radial-gradient(circle at 12% 0%,color-mix(in srgb,var(--accent) 13%,transparent),transparent 42%),
    var(--card-surface);
}
.setup-benchmark-intro::after{
  content:"";
  position:absolute;
  right:-70px;
  bottom:-100px;
  width:280px;
  height:280px;
  border:1px solid color-mix(in srgb,var(--accent) 12%,transparent);
  border-radius:50%;
  box-shadow:0 0 0 42px color-mix(in srgb,var(--accent) 3%,transparent),0 0 0 84px color-mix(in srgb,var(--accent) 2%,transparent);
  pointer-events:none;
}
.setup-benchmark-intro-head{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-columns:52px minmax(0,1fr);
  align-items:center;
  gap:17px;
}
.setup-benchmark-intro-head>.first-login-option-icon{
  width:52px;
  height:52px;
  border-color:color-mix(in srgb,var(--accent) 32%,var(--line));
  border-radius:14px;
  color:var(--accent);
  background:color-mix(in srgb,var(--accent) 9%,var(--control));
}
.setup-benchmark-intro-head>.first-login-option-icon svg{width:23px;height:23px}
.setup-benchmark-intro-head>span:last-child{display:grid;gap:6px}
.setup-benchmark-intro-head>span:last-child>small{
  color:var(--accent);
  font-size:10px;
  font-weight:750;
  letter-spacing:.16em;
}
.setup-benchmark-intro-head h3{font-size:23px}
.setup-benchmark-intro-head p{max-width:680px;font-size:12.5px}
.setup-benchmark-plan{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-columns:minmax(0,1fr) 34px minmax(0,1fr) 34px minmax(0,1fr);
  align-items:center;
}
.setup-benchmark-plan>article{
  display:grid;
  grid-template-columns:38px minmax(0,1fr);
  grid-template-rows:auto auto;
  column-gap:11px;
  row-gap:3px;
  align-items:center;
  min-height:86px;
  padding:15px;
  border:1px solid var(--line);
  border-radius:13px;
  background:color-mix(in srgb,var(--control) 82%,transparent);
  box-shadow:inset 0 1px color-mix(in srgb,var(--text) 4%,transparent);
}
.setup-benchmark-plan>article>span{
  grid-row:1/3;
  display:grid;
  width:38px;
  height:38px;
  place-items:center;
  border:1px solid color-mix(in srgb,var(--accent) 24%,var(--line));
  border-radius:10px;
  color:var(--accent);
  background:color-mix(in srgb,var(--accent) 7%,var(--background));
}
.setup-benchmark-plan>article svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7}
.setup-benchmark-plan>article strong{align-self:end;font-size:14px}
.setup-benchmark-plan>article small{align-self:start;color:var(--muted);font-size:11px;line-height:1.35}
.setup-benchmark-plan>i{
  display:block;
  height:1px;
  background:linear-gradient(90deg,var(--line),color-mix(in srgb,var(--accent) 42%,var(--line)),var(--line));
}
.setup-benchmark-plan>i::after{
  content:"";
  display:block;
  width:5px;
  height:5px;
  margin:-2px auto 0;
  border-radius:50%;
  background:color-mix(in srgb,var(--accent) 72%,var(--line));
}

.setup-topology-note.is-one-pc{
  border-color:color-mix(in srgb,#ff6678 48%,var(--line));
  background:color-mix(in srgb,#ff6678 9%,var(--control));
}
.setup-topology-note.is-one-pc>svg{color:#ff6678;stroke:#ff6678}
.setup-topology-note.is-one-pc strong{color:#ff7b89}
.setup-topology-note.is-two-pc{
  border-color:color-mix(in srgb,#55e3a4 48%,var(--line));
  background:color-mix(in srgb,#55e3a4 9%,var(--control));
}
.setup-topology-note.is-two-pc>svg{color:#55e3a4;stroke:#55e3a4}
.setup-topology-note.is-two-pc strong{color:#62e7ad}

@media(max-width:760px){
  .setup-benchmark-intro{padding:22px}
  .setup-benchmark-plan{grid-template-columns:1fr;gap:8px}
  .setup-benchmark-plan>i{width:1px;height:12px;margin:auto}
}

/* Translation Studio: dynamic placeholders are data, not translatable copy. */
