/* Contacts are the closing block of the Other page. */
[data-settings-page="other"] .brand-links-card{order:999}

.script-library>header>.script-library-actions{display:flex;flex:none;flex-direction:row;gap:6px}
.script-library>header>.script-library-actions>button{display:grid;place-items:center;line-height:0}
.script-library>header>.script-library-actions>button .lucide-icon{display:block;margin:0}
.script-folder-row{display:grid;grid-template-columns:14px 18px minmax(0,1fr);align-items:center;gap:6px;width:100%;min-height:34px;padding:5px 8px 5px calc(8px + var(--script-depth,0)*14px);border:1px solid transparent;border-radius:9px;color:var(--muted);background:transparent;cursor:pointer;text-align:left}
.script-folder-row:hover,.script-folder-row.is-active{border-color:var(--line);color:var(--text);background:color-mix(in srgb,var(--control) 76%,transparent)}
.script-folder-row svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.script-folder-row .script-folder-icon{width:17px;height:17px;color:color-mix(in srgb,var(--accent) 72%,var(--text))}
.script-folder-row .script-folder-chevron{transition:transform 150ms ease;transform:rotate(90deg)}
.script-folder-row.is-collapsed .script-folder-chevron{transform:rotate(0deg)}
.script-folder-row>span{overflow:hidden;font-size:10.5px;font-weight:650;text-overflow:ellipsis;white-space:nowrap}
