.script-list-file{display:grid;grid-template-columns:28px minmax(0,1fr);align-items:center;gap:8px;width:100%;min-height:44px;padding:7px 8px 7px calc(8px + var(--script-depth,0)*14px);border:1px solid transparent;border-radius:10px;color:color-mix(in srgb,var(--muted) 82%,transparent);background:transparent;text-align:left;user-select:none}
.script-list-file>i{display:grid;width:28px;height:28px;place-items:center;border:1px solid var(--line);border-radius:8px;background:color-mix(in srgb,var(--control) 76%,transparent)}
