.script-list-file>span{display:flex;min-width:0;flex-direction:column;gap:3px}
.script-list-file :is(strong,small){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.script-list-file strong{color:var(--muted);font-size:10.5px;font-weight:620}
.script-list-file small{font-size:8.5px}
