.profile-license-dialog-icon .lucide-icon{position:relative;z-index:1;width:31px;height:31px;fill:none;stroke:var(--accent);stroke-width:1.55;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 0 8px color-mix(in srgb,var(--accent) 24%,transparent))}
.profile-license-dialog>header{display:grid;justify-items:center;gap:7px;text-align:center}
