/* NAIM visual refinement, 2026-09-05. Shared surfaces follow the active palette. */
:root {
  --ui-card-gap: 16px;
  --ui-card-radius: 14px;
  --ui-card-padding: 18px;
  --ui-feature-padding-block: 15px;
  --ui-feature-padding-inline: 17px;
  --ui-nav-height: 66px;
  --ui-surface-panel: color-mix(in srgb, var(--card) 94%, var(--background));
  --ui-surface-raised: color-mix(in srgb, var(--card) 95%, var(--text) 5%);
  --ui-surface-recessed: color-mix(in srgb, var(--control) 70%, var(--background));
  --ui-border-quiet: color-mix(in srgb, var(--text) 8%, transparent);
  --ui-shadow-panel: 0 4px 14px color-mix(in srgb, var(--background) 18%, transparent);
  --ui-shadow-floating: 0 16px 42px color-mix(in srgb, var(--background) 45%, transparent);
}

.app-shell::before { opacity: .35; }
/* The logo, navigation and topbar share one opaque native-palette surface. */
html .app-shell > .sidebar,
html .app-shell .topbar.window-titlebar {
  background: linear-gradient(var(--sidebar), var(--sidebar)) var(--background);
  box-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}
html .app-shell > .sidebar::before,
html .app-shell > .sidebar::after,
html .app-shell .topbar.window-titlebar::before { display: none; }
.brand { text-shadow: none; letter-spacing: .035em; }
.brand-copy { gap: 5px; }
.brand small { font-weight: 400; }
.nav-tabs button { height: var(--ui-nav-height); gap: 13px; border-bottom-color: transparent; }
.nav-tabs::before {
  height: calc(var(--ui-nav-height) - 8px);
  border-color: color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 6%, transparent);
  box-shadow: none;
}
.nav-tabs button strong { font-size: 16px; font-weight: 500; }
.nav-tabs button::after { height: 24px; background: var(--accent); }
.nav-tabs button.is-active .nav-tab-icon { filter: none; }
.sidebar-bottom { background: transparent; }
.account-avatar { background: var(--control); box-shadow: none; }
.account-copy small { line-height: 1.4; }
.window-actions button,
.workspace-close,
.workspace-window-mode { box-shadow: none; }

.app-shell .page .card,
.data-studio-workspace .studio-pane > .card,
.data-studio-workspace .weapon-studio-grid > .card {
  border-color: var(--ui-border-quiet);
  background: var(--ui-surface-panel);
  box-shadow: var(--ui-shadow-panel);
}
.app-shell .page .card::after,
.data-studio-workspace .card::after { opacity: 0; }
.feature-card-title strong,
.card-head > strong,
.card-head > div > strong { font-weight: 500; line-height: 1.2; letter-spacing: -.02em; }
.setting-group-head strong { color: var(--text); font-size: 14px; font-weight: 500; }
.feature-card-title small,
.card-head small,
.feature-row small,
.master-row small,
.select-row small { line-height: 1.45; }
.range-row { box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text) 3%, transparent); }
.range-row output { font-variant-numeric: tabular-nums; }
.inline-toggles > div { border-color: var(--ui-border-quiet); background: transparent; box-shadow: none; }
.toggle input:checked + .toggle-track { box-shadow: inset 0 1px 2px color-mix(in srgb, var(--background) 16%, transparent); }
.player-element-settings,
.quiet-settings-button { box-shadow: none; }
.player-element-settings:not(:hover) { background: transparent; border-color: var(--ui-border-quiet); }
.data-studio-launcher::before { opacity: .3; }

/* Popovers and dialogs use one quiet, opaque surface. */
.custom-select-menu,
.choice-dropdown-menu,
.topbar > .market-toolbar,
.script-context-menu,
.range-bounds-popover,
#hotkey-root-menu,
#hotkey-editor-popover,
#hotkey-picker {
  /* The native stops have alpha: a solid underlay prevents page content bleeding through. */
  background: linear-gradient(180deg, var(--select-menu-top), var(--select-menu-bottom)) var(--background);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: var(--ui-shadow-floating);
  border-color: var(--line);
}
.appearance-panel,
.training-settings-panel,
.bind-manager-panel,
.humanizer-training-panel,
.humanizer-dataset-panel,
.first-login-onboarding-panel,
.market-credit-dialog,
.profile-license-dialog,
.script-unsaved-panel,
.script-file-request-panel {
  background: var(--ui-surface-panel);
  border-color: var(--line);
  box-shadow: var(--ui-shadow-floating);
